Translate("ruRU", "medivh", {
	title = "Медив",
	subtitle = "Последний Хранитель Тирисфаля",
	allegiance = "Орден Тирисфаля · Каражан",
	sections = {
		{
			title = "Обзор",
			text = [=[Медив был последним Хранителем Тирисфаля, тайным защитником, которого мудрейшие маги мира наделили силой, чтобы он противостоял {link:burning-legion}Пылающему Легиону{/link}. Его матерью была Хранительница {link:aegwynn}Эгвин{/link}, а отцом — Ниелас Аран, придворный заклинатель {link:stormwind-city}Штормграда{/link}. Он был также ближайшим другом короля {link:llane-wrynn}Ллейна Ринна{/link} и рыцаря {link:anduin-lothar}Андуина Лотара{/link}. Но силу, которая должна была хранить {link:azeroth}Азерот{/link}, отравили прежде, чем он сделал первый вдох, и именно Медив открыл {link:orcs}орк{/link}ам путь в этот мир.]=],
		},
		{
			title = "Значение",
			text = [=[Ни один смертный не сделал больше для того, чтобы настал век войн. Через него повелитель демонов {link:sargeras}Саргерас{/link} дотянулся до мира и натравил {link:horde}Орду{/link} на королевства {link:humans}людей{/link}. {link:first-war}Первая война{/link}, падение {link:stormwind-city}Штормград{/link}а и все войны, что были потом, уходят корнями в башню, где он жил.]=],
		},
		{
			title = "Отравленное рождение",
			text = [=[{link:aegwynn}Эгвин{/link} хотела, чтобы сын стал ее наследником, свободным от совета, который пытался ею править. Она не знала, что {link:sargeras}Саргерас{/link} скрыл свой дух в ней с того дня, когда она сразила его аватару. Когда был зачат Медив, повелитель демонов перешел в нерожденное дитя. Мальчик вырос смышленым и кротким и бродил по лесам королевства с друзьями, {link:llane-wrynn}Ллейн{/link}ом и {link:anduin-lothar}Лотар{/link}ом. Когда ему исполнилось четырнадцать, в нем проснулась сила Хранителя, а с ней — тьма, которая лежала под нею. Медив п{link:ogres}огр{/link}узился в сон, который не мог прервать ни один целитель. Годами он лежал на попечении священников {link:northshire-abbey}Аббатства Североземья{/link}. Проснулся он взрослым мужчиной и ничего не сказал о том, что видел во тьме.]=],
		},
		{
			title = "Каражан",
			text = [=[Медив поселился в {link:karazhan}Каражане{/link}, одинокой башне в краю, который теперь зовут {link:deadwind-pass}Перевалом Мертвого Ветра{/link}. Там, ведомый волей, что жила в нем, он дотянулся через пустоту до умирающего мира под названием {red:draenor}Дренор{/red}. Он нашел {link:orcs}орк{/link}а-чернокнижника {link:gul-dan}Гул'дана{/link}, и вместе они открыли {link:dark-portal}Темный портал{/link}. {link:kirin-tor}Кирин-Тор{/link} из {link:dalaran}Даларана{/link} прислал ему молодого ученика, {link:khadgar}Кадгара{/link}, и тот стал бояться того, что видел в башне. В Каражан пришла и полуорчиха {link:garona}Гарона{/link}, посланница Орды. Через них двоих правда наконец достигла {link:stormwind-city}Штормград{/link}а.]=],
		},
		{
			title = "Деяния",
			text = [=[• В юности он обратил свою силу против троллей юга, сражаясь рядом с друзьями, {link:llane-wrynn}Ллейн{/link}ом и {link:anduin-lothar}Лотар{/link}ом.
• Он открыл {link:dark-portal}Темный портал{/link} вместе с чернокнижником {link:gul-dan}Гул'дан{/link}ом и чернокнижниками Дренора.
• Он взял в ученики мага {link:khadgar}Кадгар{/link}а и позволил ему узнать больше, чем собирался открыть.
• Он смотрел из своей башни, как {link:horde}Орда{/link} жжет королевство его старейших друзей.]=],
		},
		{
			title = "Судьба",
			text = [=[{link:anduin-lothar}Андуин Лотар{/link} и {link:khadgar}Кадгар{/link} поднялись в {link:karazhan}Каражан{/link}, чтобы покончить с войной у самого ее корня. С помощью полуорчихи Гароны они встали против Хранителя, и там Медив был убит. В миг его смерти {link:gul-dan}Гул'дан{/link} пытался вырвать из его умирающего разума тайны Гробницы {link:sargeras}Саргерас{/link}а и за свои старания был повержен в долгое оцепенение. Медив мертв. Его башня стоит пустая и безмолвная над Перевалом Мертвого Ветра, а жители {link:duskwood}Сумеречного леса{/link} говорят, что в ее окнах до сих пор горят странные огни.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Что знал Медив, что выбрал он сам и что выбрал за него {link:sargeras}Саргерас{/link} — теперь этого уже не разделить. Летописи оставляют этот вопрос открытым.]=],
		},
	},
	bonds = {
		{ id = "aegwynn", name = "Эгвин", note = "его мать" },
		{ id = "llane-wrynn", name = "Ллейн Ринн", note = "друг его детства" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "друг и его убийца" },
		{ id = "gul-dan", name = "Гул'дан", note = "открыл с ним Темный портал" },
		{ id = "khadgar", name = "Кадгар", note = "его ученик" },
	},
})

Translate("ruRU", "aegwynn", {
	title = "Эгвин",
	subtitle = "Хранительница Тирисфаля",
	allegiance = "Орден Тирисфаля",
	sections = {
		{
			title = "Обзор",
			text = [=[Эгвин была Хранительницей Тирисфаля дольше, чем простояло большинство королевств. Тайный совет Тирисфаля, в который входили величайшие маги земель {link:humans}людей{/link} и {link:high-elves}эльфов{/link}, избрал ее своим защитником против {link:burning-legion}Пылающего Легиона{/link} и дал ей силу и жизнь длиной во много веков. Ее помнят как самую могучую из всех Хранителей и как ту, что причинила больше всего зла, вовсе того не желая.]=],
		},
		{
			title = "Значение",
			text = [=[Одной победой Эгвин нанесла Легиону самый тяжелый удар, какой он когда-либо получал в {link:azeroth}Азероте{/link}. В тот же миг она открыла дверь его величайшему торжеству. Повелитель демонов {link:sargeras}Саргерас{/link} укрылся в ней и через нее перешел в ее сына, {link:medivh}Медива{/link}.]=],
		},
		{
			title = "Хранительница",
			text = [=[Эгвин была горда и бесстрашна и не желала быть куклой совета. Она охотилась на демонов всюду, где они ступали, и носила мантию Хранителя много человеческих жизней. В {red:northrend}Нордсколе{/red} она нашла демонов, которые охотились на последних драконов севера и вытягивали из них магию. С помощью драконов она уничтожила их. Тогда перед ней в великой буре явился сам {link:sargeras}Саргерас{/link}. Эгвин сразилась с его аватарой и убила ее. Разбитое тело она запечатала в древнем чертоге, который ушел под воду в {link:great-sundering}Великий Раскол{/link}, чтобы оно никогда не восстало. Она верила, что хозяин Легиона побежден. Она не знала, что его дух проскользнул в ее собственный.]=],
		},
		{
			title = "Наследник Хранительницы",
			text = [=[За долгие годы, что были потом, Эгвин отдалилась от совета. Она решила, что его члены вмешиваются в дела королей, и постановила, что следующего Хранителя они не выберут никогда. Она взяла в супруги заклинателя Ниеласа Арана, служившего при дворе {link:stormwind-city}Штормграда{/link}, и родила ему сына. Силу Тирисфаля она вложила в ребенка, чтобы та пробудилась, когда он войдет в возраст. Потом она оставила мальчика отцу и удалилась от мира.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она много веков носила мантию Хранителя и уничтожала демонов по всем Восточным королевствам.
• Она защитила драконов Нордскола от охотников Легиона.
• Она убила аватару, в которой явился {link:sargeras}Саргерас{/link}, и п{link:ogres}огр{/link}ебла ее тело под морем.
• Она бросила вызов совету Тирисфаля и сама выбрала себе наследника.]=],
		},
		{
			title = "Судьба",
			text = [=[Эгвин пережила сына, которого создала. Когда открылся {link:dark-portal}Темный портал{/link} и пришла {link:horde}Орда{/link}, мир узнал, чего стоила ее гордыня. {link:medivh}Медив{/link} пал в {link:karazhan}Каражан{/link}е, и с ним прервалась череда Хранителей. Сама Эгвин ушла в изгнание, растратив свою силу. Среди ученых {link:theramore-isle}Терамора{/link} шепчут, что старая женщина великой мудрости какое-то время жила в глуши {link:kalimdor}Калимдора{/link} и давала советы леди {link:jaina-proudmoore}Джайне Праудмур{/link}. Немногие знают ее имя, и те, кто знает, держат его при себе.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Летописи не говорят, как Эгвин была избрана впервые и сколько всего лет она носила мантию. Здесь записано лишь то, что достоверно.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Медив", note = "ее сын" },
		{ id = "jaina-proudmoore", name = "Джайна Праудмур", note = "которой она, как говорят, давала советы" },
	},
})

Translate("ruRU", "llane-wrynn", {
	title = "Ллейн Ринн",
	subtitle = "Король Штормграда в Первую войну",
	allegiance = "Королевство Штормград · Дом Риннов",
	aliases = { "Ллейн", "король Ллейн" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ллейн Ринн был королем {link:stormwind-city}Штормград{/link}а, когда {link:horde}Орда{/link} прошла через {link:dark-portal}Темный портал{/link}. Он был гордым и отважным правителем, другом детства {link:medivh}Медива{/link} и {link:anduin-lothar}Андуина Лотара{/link} и отцом короля {link:varian-wrynn}Вариана Ринна{/link}. Он провел свой народ через долгую муку {link:first-war}Первой войны{/link} и погиб в собственной крепости, когда пал его город.]=],
		},
		{
			title = "Значение",
			text = [=[Ллейн был последним королем старого {link:stormwind-city}Штормград{/link}а. Его смерть стала концом державы, которая поколениями стояла одна и гордо. Из ее руин вышел {link:alliance}Альянс{/link}, ибо уцелевшие, которых он оставил после себя, понесли весть об {link:orcs}орк{/link}ах на север, в {link:lordaeron}Лордерон{/link}.]=],
		},
		{
			title = "Юность",
			text = [=[Ллейн вырос рядом с двумя необыкновенными мальчиками: это были {link:anduin-lothar}Андуин Лотар{/link}, наследник древнего рода, и {link:medivh}Медив{/link}, сын придворного заклинателя. Трое были неразлучны. Когда Медив п{link:ogres}огр{/link}узился в свой долгий сон, Ллейн возмужал без него и радовался, когда друг проснулся. Эта дружба ослепит его в грядущие годы.]=],
		},
		{
			title = "Первая война",
			text = [=[Когда в Черных топях увидели странных существ, Ллейн послал рыцаря {link:anduin-lothar}Лотар{/link}а узнать, кто они. Это были {link:orcs}орк{/link}и, и они были лишь первыми. Ллейн назвал его своим защитником и разослал гонцов в другие королевства людей, но рассказу мало кто поверил. Годами {link:stormwind-city}Штормград{/link} сражался один. Деревни горели по всему {link:elwynn-forest}Элвиннскому лесу{/link}, {link:westfall}Западному Краю{/link} и {link:redridge-mountains}Красногорью{/link}. {link:horde}Орда{/link} осадила столицу и была отброшена, ибо Лотар внезапно ударил ей в тыл. Когда {link:khadgar}Кадгар{/link} и полуорчиха {link:garona}Гарона{/link} предупредили короля, что захватчиков привел сам {link:medivh}Медив{/link}, Ллейн не поверил, что друг мог его предать.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он назвал рыцаря Андуина {link:anduin-lothar}Лотар{/link}а защитником королевства и доверил ему его оборону.
• Он послал другим королевствам людей весть об {link:orcs}орк{/link}ах.
• Он удержал {link:stormwind-city}Штормград{/link} в первой великой осаде Орды.
• Он приблизил к себе полуорчиху Гарону после того, как пал {link:medivh}Медив{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[После того как {link:medivh}Медив{/link} погиб, {link:orcs}орк{/link} {link:orgrim-doomhammer}Оргрим Молот Рока{/link} захватил власть над Ордой и снова повел ее на {link:stormwind-city}Штормград{/link}. Стены были пробиты, но Ллейн удерживал крепость. {link:garona}Гарона{/link}, ставшая его доверенной советницей, все еще была подчинена воле чернокнижников Орды. Она убила короля в его покоях. Юный принц {link:varian-wrynn}Вариан{/link} видел, как умер его отец. Штормград пал, и {link:horde}Орда{/link} сровняла его с землей. {link:anduin-lothar}Лотар{/link} собрал уцелевших и увел их за море, в {link:lordaeron}Лордерон{/link}. С тех пор королевство, которым правил Ллейн, отстроили, и его сын сидел на его троне до своего недавнего исчезновения. Его внук, {link:anduin-wrynn}Андуин Ринн{/link}, ждет теперь в отстроенной крепости; он назван в честь защитника, который спас его семью.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Летописи мало говорят о королеве, которая была женой короля, и о годах его правления до того, как открылся Портал.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Медив", note = "друг его детства" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "его защитник" },
		{ id = "varian-wrynn", name = "Вариан Ринн", note = "его сын" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "вел Орду, которая взяла его город" },
		{ id = "garona", name = "Гарона", note = "его советница и его убийца" },
	},
})

Translate("ruRU", "anduin-lothar", {
	title = "Андуин Лотар",
	subtitle = "Лев Азерота",
	allegiance = "Королевство Штормград · Альянс Лордерона",
	aliases = { "Лотар", "сэр Андуин Лотар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сэр Андуин Лотар был защитником {link:stormwind-city}Штормград{/link}а в {link:first-war}Первую войну{/link} и первым верховным главнокомандующим {link:alliance}Альянса{/link} во {link:second-war}Вторую войну{/link}. Он был последним известным наследником королевской крови {link:arathor}Аратора{/link}, древней империи, из которой вышли королевства людей. Солдаты звали его Львом {link:azeroth}Азерот{/link}а. Без него народы {link:humans}людей{/link}, быть может, никогда не встали бы вместе.]=],
		},
		{
			title = "Значение",
			text = [=[Лотар спас {link:stormwind-city}Штормград{/link} дважды: в первый раз — когда вывел его народ из пепла, во второй — когда убедил королей севера сражаться за него. {link:alliance}Альянс{/link}, который он выковал, стоит до сих пор, а внук его короля носит его имя.]=],
		},
		{
			title = "Первая война",
			text = [=[Лотар был другом отрочества {link:llane-wrynn}Ллейна Ринна{/link} и {link:medivh}Медива{/link}. Когда в Черных топях впервые увидели {link:orcs}орк{/link}ов, король послал его на разведку, и он вернулся с вестью о войне. Ллейн сделал его защитником королевства. Лотар годами сражался по всей державе. Когда {link:horde}Орда{/link} в первый раз осадила {link:stormwind-city}Штормград{/link}, он провел рыцарей королевства морем в обход и ударил ей в тыл, сломив приступ. С молодым магом {link:khadgar}Кадгаром{/link} он поднялся в {link:karazhan}Каражан{/link} и встал против своего старейшего друга, и там Хранитель был убит. Но королевство спасти не удалось. Когда Штормград пал, Лотар увел уцелевших на север, за море.]=],
		},
		{
			title = "Вторая война",
			text = [=[В {link:lordaeron}Лордероне{/link} Лотар предстал перед королем {link:terenas-menethil}Теренасом Менетилом{/link} и перед владыками северных держав и предупредил их, что следующими {link:horde}Орда{/link} придет за ними. Они прислушались. Родился {link:alliance}Альянс Лордерона{/link}, и Лотар был назван его главнокомандующим. К Альянсу примкнули высшие эльфы {link:quel-thalas}Кель'Таласа{/link}, ибо за ними был древний долг перед кровью {link:arathor}Аратор{/link}а, а Лотар был ее последним наследником. Со своими помощниками — это были {link:khadgar}Кадгар{/link} и молодой паладин {link:turalyon}Туралион{/link} — он бился с Ордой по всем северным королевствам и отбросил ее на юг.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он разведал первых {link:orcs}орк{/link}ов в Черных топях и предупредил своего короля.
• Он снял первую осаду {link:stormwind-city}Штормград{/link}а ударом с моря.
• Он убил Хранителя в {link:karazhan}Каражан{/link}е, и рядом с ним был {link:khadgar}Кадгар{/link}.
• Он увел народ Штормграда в изгнание в {link:lordaeron}Лордерон{/link}.
• Он убедил королевства людей объединиться и командовал их армиями.]=],
		},
		{
			title = "Судьба",
			text = [=[В конце Второй войны Лотар преследовал Орду до {link:blackrock-mountain}Черной горы{/link} в {link:burning-steppes}Пылающих степях{/link}. Там, в битве у подножия горы, он пал от руки вождя {link:orgrim-doomhammer}Оргрима Молота Рока{/link}. Его смерть не сломила {link:alliance}Альянс{/link}. {link:turalyon}Туралион{/link} поднял его меч, сплотил скорбящих солдат и сокрушил Орду. {link:stormwind-city}Штормград{/link} был отвоеван, и позже король {link:varian-wrynn}Вариан Ринн{/link} назвал своего сына в честь защитника.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Ллейн Ринн", note = "его король и друг" },
		{ id = "medivh", name = "Медив", note = "друг и враг" },
		{ id = "terenas-menethil", name = "Теренас Менетил", note = "дал ему начало над Альянсом" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "его убийца" },
		{ id = "turalyon", name = "Туралион", note = "его помощник и преемник" },
		{ id = "anduin-wrynn", name = "Андуин Ринн", note = "назван в его честь" },
	},
})

Translate("ruRU", "tiffin-wrynn", {
	title = "Тиффин Ринн",
	subtitle = "Королева Штормграда",
	allegiance = "Королевство Штормград · Дом Риннов",
	aliases = { "Тиффин", "королева Тиффин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Тиффин Ринн была королевой при короле {link:varian-wrynn}Вариане Ринне{/link} и матерью принца {link:anduin-wrynn}Андуина Ринна{/link}. Она сидела рядом с мужем в годы после {link:second-war}Второй войны{/link}, когда {link:stormwind-city}Штормград{/link} вновь поднимался из пепла. Увидеть город достроенным ей не довелось. Она погибла во время бунта каменщиков, став жертвой ссоры между знатью короны и теми, кто заново возвел ее стены.]=],
		},
		{
			title = "Значение",
			text = [=[Смерть королевы — одна из тихих ран нового {link:stormwind-city}Штормград{/link}а. Она отняла мать у наследника королевства и жену у его короля. Она же стала мигом, когда гнев каменщиков обернулся открытым мятежом, из которого родилось {link:defias-brotherhood}Братство Справедливости{/link}.]=],
		},
		{
			title = "Восстановление",
			text = [=[После Второй войны изгнанники {link:stormwind-city}Штормград{/link}а вернулись домой и нашли свой город в руинах. {link:stonemasons-guild}Гильдия каменщиков{/link}, которую вел {link:edwin-vancleef}Эдвин ван Клиф{/link}, годами трудилась, чтобы поднять его заново. {link:varian-wrynn}Вариан{/link}, сын {link:llane-wrynn}Ллейна Ринна{/link}, занял трон своих предков. Тиффин стала его королевой и со временем родила ему сына, которого назвали в честь защитника {link:anduin-lothar}Андуина Лотара{/link}. Какое-то время казалось, что королевство снова узнает мир.]=],
		},
		{
			title = "Бунт",
			text = [=[{link:house-of-nobles}Палата знати{/link} обещала заплатить каменщикам за их труд. Когда работа была кончена, знать отказалась. Каменщики вышли с протестом на улицы столицы, и протест перерос в бунт. В смятении королеву сразили насмерть. Каменщиков с позором выгнали из города, и самые озлобленные из них бежали в {link:westfall}Западный Край{/link}. Там они повязали красные платки, и с тех пор их братство терзает королевство.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она была королевой {link:stormwind-city}Штормград{/link}а в годы после его восстановления.
• Она родила королю сына и наследника, принца Андуина.]=],
		},
		{
			title = "Судьба",
			text = [=[Тиффин мертва. Ее сын еще мальчик, и в эти дни он ждет в крепости {link:stormwind-city}Штормград{/link}а, пока судьба его отца остается неизвестной, а регентом правит верховный лорд {link:bolvar-fordragon}Болвар Фордрагон{/link}. Каменщики, некогда служившие короне, теперь ведут против нее собственную войну из шахт и с ферм Западного Края. Многие в Штормграде до сих пор говорят о королеве с любовью, а о ее смерти — со стыдом.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Мало написано о том, как Тиффин жила до того, как стала королевой. Летописи говорят о ее браке, о ее сыне и о ее смерти и почти ничего — о ее собственных словах и делах. Эта запись не заполняет то молчание догадками.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Вариан Ринн", note = "ее муж" },
		{ id = "anduin-wrynn", name = "Андуин Ринн", note = "ее сын" },
		{ id = "llane-wrynn", name = "Ллейн Ринн", note = "отец ее мужа" },
		{ id = "edwin-vancleef", name = "Эдвин ван Клиф", note = "вел каменщиков, чей бунт отнял у нее жизнь" },
	},
})

Translate("ruRU", "terenas-menethil", {
	title = "Теренас Менетил",
	subtitle = "Король Лордерона",
	allegiance = "Королевство Лордерон · Альянс Лордерона",
	aliases = { "Теренас", "король Теренас" },
	sections = {
		{
			title = "Обзор",
			text = [=[Король Теренас Менетил Второй правил {link:lordaeron}Лордероном{/link}, величайшим из северных королевств {link:humans}людей{/link}. Именно в его столице был основан {link:alliance}Альянс{/link}, и под его знаменем {link:horde}Орда{/link} была разбита во {link:second-war}Второй войне{/link}. Он был отцом принца {link:arthas-menethil}Артаса Менетила{/link} и принцессы Калии. Он погиб от руки сына, и его королевство погибло вместе с ним.]=],
		},
		{
			title = "Значение",
			text = [=[Теренас был замковым камнем {link:alliance}Альянс{/link}а {link:lordaeron}Лордерон{/link}а. Он принял беженцев {link:stormwind-city}Штормград{/link}а и выслушал рыцаря {link:anduin-lothar}Андуина Лотара{/link}, когда другие короли слушать не стали. Но мир, который настал после его победы, истрепался при его правлении, а конечная судьба его державы — самая мрачная в истории человечества.]=],
		},
		{
			title = "Альянс",
			text = [=[Когда {link:anduin-lothar}Лотар{/link} привел изгнанников {link:stormwind-city}Штормград{/link}а на север, Теренас созвал владык человеческих держав в свою столицу. {link:gilneas}Гилнеас{/link}, {link:kul-tiras}Кул Тирас{/link}, {link:stromgarde-keep}Стромгард{/link}, {link:alterac-mountains}Альтерак{/link} и {link:dalaran}Даларан{/link} прислали своих правителей и послов, а позже к ним примкнули высшие эльфы {link:quel-thalas}Кель'Таласа{/link}. Теренас поручил рыцарю Лотару начало над объединенными армиями. Собственные земли {link:lordaeron}Лордерон{/link}а тяжко пострадали в войне, но в конце концов {link:horde}Орда{/link} была сломлена, а ее {link:orcs}орк{/link}и взяты в плен.]=],
		},
		{
			title = "Истрепанный мир",
			text = [=[После войны Теренас приказал держать пленных {link:orcs}орк{/link}ов в {link:ogres}огр{/link}омных лагерях. Лагеря стоили дорого, и, чтобы платить за них, он обложил податью другие державы. Росли распри из-за лагерей и из-за судьбы вероломного королевства {link:alterac-mountains}Альтерак{/link}. Одно за другим из {link:alliance}Альянс{/link}а вышли {link:gilneas}Гилнеас{/link}, {link:stromgarde-keep}Стромгард{/link} и {link:quel-thalas}Кель'Талас{/link}. Когда по северным пашням {link:lordaeron}Лордерон{/link}а стала расходиться странная чума, король послал покончить с ней своего сына и паладина {link:uther-the-lightbringer}Утера Светоносного{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он принял беженцев {link:stormwind-city}Штормград{/link}а в своем королевстве.
• Он основал {link:alliance}Альянс Лордерона{/link} и отдал начало над ним рыцарю Андуину {link:anduin-lothar}Лотар{/link}у.
• Он приказал построить лагеря для пленных после Второй войны.
• Он послал против чумы на севере принца {link:arthas-menethil}Артас{/link}а и паладина {link:uther-the-lightbringer}Утер{/link}а.]=],
		},
		{
			title = "Судьба",
			text = [=[{link:arthas-menethil}Артас{/link} вернулся домой из {red:northrend}Нордскола{/red} героем, и жители столицы усыпали его путь лепестками цветов. Принц вошел в тронный зал, преклонил колени перед отцом, а затем убил его руническим клинком, {red:frostmourne}Ледяной Скорбью{/red}. Со смертью короля королевство досталось {link:scourge}Плети{/link}. Позже {link:uther-the-lightbringer}Утер{/link} вез прах короля в урне в сторону {link:quel-thalas}Кель'Таласа{/link}, но Артас сразил паладина и выбросил прах. {link:capital-city}Столица{/link} короля лежит в руинах, а под ней {link:forsaken}Отрекшиеся{/link}, которых ведет леди {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link}, построили {link:undercity}Подгород{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Артас Менетил", note = "его сын и его убийца" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "главнокомандующий его Альянса" },
		{ id = "uther-the-lightbringer", name = "Утер Светоносный", note = "его верный паладин" },
		{ id = "alonsus-faol", name = "Алонсий Фаол", note = "архиепископ его веры" },
	},
})

Translate("ruRU", "arthas-menethil", {
	title = "Артас Менетил",
	subtitle = "Падший принц",
	allegiance = "Плеть (прежде королевство Лордерон, рыцари Серебряной Длани)",
	aliases = { "Артас", "принц Артас" },
	sections = {
		{
			title = "Обзор",
			text = [=[Артас Менетил был наследным принцем {link:lordaeron}Лордерона{/link}, рыцарем Серебряной Длани и учеником паладина {link:uther-the-lightbringer}Утера Светоносного{/link}. Он был храбр, любим и горд. Он отправился спасать свой народ от чумы нежити, а кончил тем, что погубил его. Он убил своего отца, короля {link:terenas-menethil}Теренаса Менетила{/link}, и провел {link:scourge}Плеть{/link} по всему северу. Теперь он правит нежитью из ледяного сердца {red:northrend}Нордскола{/red}.]=],
		},
		{
			title = "Значение",
			text = [=[Ни одно падение в истории человечества не было столь великим и столь страшным. Имя принца проклинают во всякой земле, которая знала {link:alliance}Альянс{/link}, а земли, которые он опустошил, до сих пор зовут Чумными.]=],
		},
		{
			title = "Принц",
			text = [=[Артас был единственным сыном короля. {link:uther-the-lightbringer}Утер{/link} обучил его как паладина {link:holy-light}Света{/link}, и его приняли в орден Серебряной Длани. Когда чума поразила северные пашни {link:lordaeron}Лордерон{/link}а, король послал их обоих покончить с ней. Рядом с ним шла {link:jaina-proudmoore}Джайна Праудмур{/link} из {link:dalaran}Даларана{/link}, и по следу болезни Артас вышел на некроманта {link:kel-thuzad}Кел'Тузада{/link} и его {link:cult-of-the-damned}Культ Проклятых{/link} и убил некроманта. Но чума все расходилась. В Стратхольме Артас обнаружил, что зерно города заражено и что все, кто его ел, восстанут нежитью. Он приказал очистить город. Утер и Джайна отказались в этом участвовать, и Артас совершил {link:culling-of-stratholme}Очищение Стратхольма{/link} без них.]=],
		},
		{
			title = "Падение",
			text = [=[Артас преследовал повелителя ужаса Мал'Ганиса до Нордскола. Там он сжег собственные корабли, чтобы его люди не могли повернуть назад, и взял в руки проклятый рунический клинок, {red:frostmourne}Ледяную Скорбь{/red}. Им он убил демона Мал'Ганиса, но меч забрал его душу. Он вернулся домой в {link:lordaeron}Лордерон{/link} слугой {red:lich-king}Короля-лича{/red}. В тронном зале он убил своего отца, и королевство пало. Он уничтожил орден Серебряной Длани, убил паладина {link:uther-the-lightbringer}Утер{/link}а и вновь поднял некроманта {link:kel-thuzad}Кел'Тузад{/link}а у Солнечного Колодца, опустошив перед тем {link:quel-thalas}Кель'Талас{/link}. Он убил предводительницу следопытов {link:sylvanas-windrunner}Сильвану Ветрокрылую{/link} и подчинил ее дух своей воле.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он совершил {link:culling-of-stratholme}Очищение Стратхольма{/link}.
• Он убил короля {link:terenas-menethil}Теренас{/link}а и отдал {link:lordaeron}Лордерон{/link} Плети.
• Его рукой убит {link:uther-the-lightbringer}Утер Светоносный{/link}.
• Он разорил {link:quel-thalas}Кель'Талас{/link} и осквернил Солнечный Колодец, чтобы {link:kel-thuzad}Кел'Тузад{/link} восстал личом.
• Он открыл {link:burning-legion}Пылающему Легиону{/link} путь в {link:dalaran}Даларан{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[После {link:battle-of-mount-hyjal}Битвы у горы Хиджал{/link} сила Короля-лича пошла на убыль, и Артас утратил власть над {link:lordaeron}Лордерон{/link}ом. {link:sylvanas-windrunner}Сильвана{/link} вырвалась из-под его воли, и {link:forsaken}Отрекшиеся{/link} восстали против него. По зову своего хозяина Артас вернулся в Нордскол. У ледника Ледяная Корона он сразился с {link:illidan-stormrage}Иллиданом Яростью Бури{/link} и победил. Затем он взошел на Ледяной Трон и надел шлем Короля-лича, и двое стали одним. Ныне Артас царствует в Нордсколе как Король-лич. В Лордероне его именем {link:scourge}Плеть{/link}ю повелевает {link:kel-thuzad}Кел'Тузад{/link}. {link:muradin-bronzebeard}Мурадин Бронзобород{/link}, который когда-то пошел за ним на север, домой так и не вернулся.]=],
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "Теренас Менетил", note = "его отец и его жертва" },
		{ id = "uther-the-lightbringer", name = "Утер Светоносный", note = "его учитель и его жертва" },
		{ id = "jaina-proudmoore", name = "Джайна Праудмур", note = "его утраченная любовь" },
		{ id = "kel-thuzad", name = "Кел'Тузад", note = "враг, потом слуга" },
		{ id = "ner-zhul", name = "Нер'зул", note = "Король-лич, с которым он слился" },
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "враг у ледника Ледяная Корона" },
		{ id = "sylvanas-windrunner", name = "Сильвана Ветрокрылая", note = "его жертва и враг" },
	},
})

Translate("ruRU", "uther-the-lightbringer", {
	title = "Утер Светоносный",
	subtitle = "Первый из паладинов",
	allegiance = "Рыцари Серебряной Длани · Церковь Света",
	aliases = { "Утер", "лорд Утер" },
	sections = {
		{
			title = "Обзор",
			text = [=[Утер Светоносный был первым паладином {link:holy-light}Света{/link} и предводителем рыцарей Серебряной Длани. Вере он учился подле архиепископа {link:alonsus-faol}Алонсия Фаола{/link}, во {link:second-war}Вторую войну{/link} бился с {link:horde}Ордой{/link} по всему северу и обучал принца {link:arthas-menethil}Артаса Менетила{/link}. Он был учителем и другом принца и погиб от руки принца.]=],
		},
		{
			title = "Значение",
			text = [=[Утер показал королевствам людей, что вера и сталь могут стоять вместе. Орден, который он вел, целое поколение защищал {link:lordaeron}Лордерон{/link}, и его имя до сих пор с почтением произносит каждый паладин в мире.]=],
		},
		{
			title = "Серебряная Длань",
			text = [=[После {link:first-war}Первой войны{/link} на север пришла весть, что {link:horde}Орда{/link} перебила священников {link:northshire-abbey}Аббатства Североземья{/link}. {link:alonsus-faol}Алонсий Фаол{/link} решил, что слуги {link:holy-light}Свет{/link}а больше не будут стоять беззащитными. С благословения рыцаря {link:anduin-lothar}Андуина Лотара{/link} он собрал воинов крепкой веры и научил их владеть святой силой в бою. Утер был первым среди них. Когда их обучение закончилось, архиепископ назвал его предводителем новых рыцарей Серебряной Длани. Утер и его паладины, среди которых были {link:turalyon}Туралион{/link} и {link:tirion-fordring}Тирион Фордринг{/link}, сражались всю Вторую войну и несли исцеление и надежду туда, где бои были тяжелее всего.]=],
		},
		{
			title = "Принц",
			text = [=[В годы мира Утер взял юного принца {link:arthas-menethil}Артас{/link}а в ученики и принял его в орден. Когда на севере {link:lordaeron}Лордерон{/link}а вспыхнула чума, король {link:terenas-menethil}Теренас Менетил{/link} послал их обоих покончить с ней. В Стратхольме Артас приказал перебить жителей города прежде, чем чума их поднимет. Утер отказался. Он не желал разить живых, и Артас отстранил его от службы. {link:culling-of-stratholme}Очищение Стратхольма{/link} свершилось без него.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он был первым паладином, которого посвятил {link:alonsus-faol}архиепископ Алонсий Фаол{/link}, и вел рыцарей Серебряной Длани.
• Он бился с Ордой во Вторую войну.
• Он обучал принца {link:arthas-menethil}Артас{/link}а путям {link:holy-light}Свет{/link}а.
• Он отказался участвовать в Очищении Стратхольма.]=],
		},
		{
			title = "Судьба",
			text = [=[Когда {link:arthas-menethil}Артас{/link} вернулся из {red:northrend}Нордскола{/red} и убил своего отца, принц обратился против ордена, который его вырастил. Он разбил Серебряную Длань и стал охотиться на ее рыцарей. Утер и его последние паладины охраняли урну с прахом короля {link:terenas-menethil}Теренас{/link}а. Артас пришел за ней, и ученик убил учителя руническим клинком, {red:frostmourne}Ледяной Скорбью{/red}. Теперь в {link:western-plaguelands}Западных Чумных землях{/link} стоит гробница в память о паладине — место скорби в мертвом краю. Некоторые из паладинов, которых он обучил, еще живы, и они помнят его.]=],
		},
	},
	bonds = {
		{ id = "alonsus-faol", name = "Алонсий Фаол", note = "его наставник" },
		{ id = "arthas-menethil", name = "Артас Менетил", note = "его ученик и его убийца" },
		{ id = "terenas-menethil", name = "Теренас Менетил", note = "его король" },
		{ id = "turalyon", name = "Туралион", note = "брат по Серебряной Длани" },
		{ id = "tirion-fordring", name = "Тирион Фордринг", note = "брат по Серебряной Длани" },
	},
})

Translate("ruRU", "alonsus-faol", {
	title = "Алонсий Фаол",
	subtitle = "Архиепископ Света",
	allegiance = "Церковь Света · Рыцари Серебряной Длани",
	aliases = { "архиепископ Фаол", "архиепископ Алонсий Фаол" },
	sections = {
		{
			title = "Обзор",
			text = [=[Алонсий Фаол был архиепископом Церкви {link:holy-light}Света{/link}, духовным отцом королевств людей в век {link:second-war}Второй войны{/link}. Это был невысокий, тучный старик с белой бородой и добрым лицом, которого любили и простолюдины, и короли. Он основал орден рыцарей Серебряной Длани и посвятил первого из паладинов, {link:uther-the-lightbringer}Утера Светоносного{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[До него слуги {link:holy-light}Свет{/link}а исцеляли и молились, пока другие сражались. После него они поехали на войну. Ордена паладинов во всех землях людей и молодые паладины, которых теперь обучают в {link:northshire-abbey}Аббатстве Североземья{/link}, — все идут дорогой, которую он открыл.]=],
		},
		{
			title = "Серебряная Длань",
			text = [=[Фаол давно служил вере и взял юного {link:uther-the-lightbringer}Утер{/link}а в ученики за много лет до прихода {link:orcs}орк{/link}ов. В {link:first-war}Первую войну{/link} {link:horde}Орда{/link} сожгла аббатство Североземья и перебила его священников. Когда уцелевшие жители {link:stormwind-city}Штормграда{/link} добрались до {link:lordaeron}Лордерона{/link}, архиепископ услышал о резне и решил, что такое не повторится. Вместе с рыцарем {link:anduin-lothar}Андуином Лотаром{/link} он основал орден святых воинов. Он выбрал рыцарей крепкой веры и научил их призывать {link:holy-light}Свет{/link} в бою. Утер, {link:turalyon}Туралион{/link}, {link:tirion-fordring}Тирион Фордринг{/link} и еще несколько человек были первыми. Когда их обучение завершилось, Фаол назвал паладина Утера предводителем рыцарей Серебряной Длани.]=],
		},
		{
			title = "Мир",
			text = [=[Фаол был при том, как владыки человеческих держав собрались в столице {link:lordaeron}Лордерон{/link}а. Говорят, он помогал остужать их нрав, когда их споры накалялись. После войны он обратил свои заботы на восстановление юга. Он посылал своих священников и паладинов всюду, где в них была нужда, и поддержал возведение нового Собора {link:holy-light}Свет{/link}а в {link:stormwind-city}Штормград{/link}е и восстановление Североземья.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он обучил своего ученика {link:uther-the-lightbringer}Утер{/link}а вере {link:holy-light}Свет{/link}а.
• Он основал орден рыцарей Серебряной Длани вместе с рыцарем Андуином {link:anduin-lothar}Лотар{/link}ом.
• Он посвятил первых паладинов и назвал их предводителем паладина Утера.
• Он давал советы владыкам {link:alliance}Альянс{/link}а во Вторую войну.
• Он помогал восстанавливать {link:stormwind-city}Штормград{/link} и {link:northshire-abbey}Аббатство Североземья{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[Фаол умер в годы после Второй войны. Летописи не говорят как. Его ученик {link:archbishop-benedictus}Бенедикт{/link} стал архиепископом после него и до сих пор хранит {link:cathedral-of-light}Собор Света{/link} в {link:stormwind-city}Штормград{/link}е. Архиепископа похоронили в {link:tirisfal-glades}Тирисфальских лесах{/link}, в гробнице, которую зовут Могилой Фаола. Тот край принадлежит теперь нежити, и {link:forsaken}Отрекшиеся{/link} ходят там, куда некогда приходили молиться верующие.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Ни одна летопись не говорит, как умер Алонсий Фаол и когда. Немного в них записано и о его жизни до того, как он стал архиепископом.]=],
		},
	},
	bonds = {
		{ id = "uther-the-lightbringer", name = "Утер Светоносный", note = "его ученик" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "основал с ним Серебряную Длань" },
		{ id = "terenas-menethil", name = "Теренас Менетил", note = "его король в Лордероне" },
	},
})

Translate("ruRU", "orgrim-doomhammer", {
	title = "Оргрим Молот Рока",
	subtitle = "Вождь Орды во Вторую войну",
	allegiance = "Орда · клан Черной горы",
	aliases = { "Оргрим", "вождь Молот Рока" },
	sections = {
		{
			title = "Обзор",
			text = [=[Оргрим Молот Рока был вождем {link:horde}Орды{/link}, который завоевал {link:stormwind-city}Штормград{/link} и вел {link:orcs}орк{/link}ов во {link:second-war}Вторую войну{/link}. Он был воином клана Черной горы, носил великий молот своего рода и был старейшим другом вождя Дуротана из клана Северного Волка. Он ненавидел чернокнижников, которые совратили его народ, и пытался, на свой лад, освободить орков. В конце жизни он нашел орка, который завершит это дело: это был {link:thrall}Тралл{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Молот Рока сделал Орду единым войском с единой волей. При нем она подошла к завоеванию королевств людей ближе, чем когда-либо прежде. Но величайшее его наследие — не завоевание. Это новая {link:horde}Орда{/link}, и ее столица {link:orgrimmar}Оргриммар{/link} носит его имя.]=],
		},
		{
			title = "Первая война",
			text = [=[В первые годы войны Оргрим был вторым при вожде Черноруке, кукле чернокнижника {link:gul-dan}Гул'дана{/link}. Когда убийцы, посланные чернокнижником, умертвили вождя Дуротана, сдерживать гнев Оргрим больше не мог. После того как погиб {link:medivh}Медив{/link}, он вызвал вождя Чернорука на поединок насмерть и размозжил ему череп Молотом Рока. Став вождем, он запретил темную магию, которая отравила Дренор. Он снова повел Орду на {link:stormwind-city}Штормград{/link}, и на этот раз город пал. Затем он нашел логово {link:shadow-council}Совет{/link}а Теней, круга чернокнижников, и перебил большинство из них.]=],
		},
		{
			title = "Вторая война",
			text = [=[Молот Рока пощадил чернокнижника {link:gul-dan}Гул'дан{/link}а, который обещал ему новое оружие. Он призвал всю силу Орды и двинулся на север. Он взял {link:kingdom-of-ironforge}земли дворфов{/link} в Каз Модане, заключил союз с лесными троллями Амани и пустил в бой красных драконов клана Драконьей Пасти. Его армии жгли леса {link:quel-thalas}Кель'Таласа{/link} и осадили столицу {link:lordaeron}Лордерона{/link}. Тогда Гул'дан предал его и увел большую часть Орды. Осада провалилась. У {link:blackrock-mountain}Черной горы{/link} Молот Рока убил в бою рыцаря {link:anduin-lothar}Андуина Лотара{/link}, но паладин {link:turalyon}Туралион{/link} сплотил {link:alliance}Альянс{/link}, и {link:horde}Орда{/link} была сокрушена.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он убил вождя Чернорука и сам стал вождем.
• Он завоевал {link:stormwind-city}Штормград{/link} и закончил {link:first-war}Первую войну{/link}.
• Он уничтожил {link:shadow-council}Совет Теней{/link}.
• Он привел Орду к воротам столицы {link:lordaeron}Лордерон{/link}а.
• Он убил рыцаря Андуина {link:anduin-lothar}Лотар{/link}а у Черной горы.]=],
		},
		{
			title = "Судьба",
			text = [=[Молот Рока попал в плен, и его в цепях показывали в столице {link:lordaeron}Лордерон{/link}а. Он бежал и много лет жил скрываясь. Когда его разыскал молодой {link:thrall}Тралл{/link}, сын вождя Дуротана, старый вождь узнал его сразу. Он вместе с ним освобождал {link:orcs}орк{/link}ов из лагерей для пленных и пал в одной из тех битв в холмах {link:hillsbrad-foothills}Хилсбрада{/link}. Перед смертью он назвал новым вождем своего молодого соратника. Теперь Тралл носит в {link:orgrimmar}Оргриммар{/link}е его черные доспехи и его молот.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "его наследник, новый вождь" },
		{ id = "gul-dan", name = "Гул'дан", note = "чернокнижник, которого он презирал" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "враг, которого он убил" },
		{ id = "llane-wrynn", name = "Ллейн Ринн", note = "король, чей город он взял" },
		{ id = "grom-hellscream", name = "Гром Адский Крик", note = "такой же вождь клана" },
	},
})

Translate("ruRU", "grom-hellscream", {
	title = "Гром Адский Крик",
	subtitle = "Вождь клана Песни Войны",
	allegiance = "Орда · клан Песни Войны",
	aliases = { "Громмаш", "Громмаш Адский Крик" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гром Адский Крик был вождем клана Песни Войны, самым свирепым из военачальников {link:orcs}орков{/link} и вернейшим другом вождя {link:thrall}Тралла{/link}. Он первым из орков выпил кровь демона {link:mannoroth}Маннорота{/link} и тем привязал свой народ к {link:burning-legion}Пылающему Легиону{/link}. Он же был орком, который разорвал эти узы ценой собственной жизни.]=],
		},
		{
			title = "Значение",
			text = [=[Проклятие {link:orcs}орк{/link}ов началось с него и им же кончилось. Его смерть в {link:ashenvale}Ясеневом лесу{/link} освободила орков от демонической крови, и нынешняя {link:horde}Орда{/link} обязана свободой его последнему бою.]=],
		},
		{
			title = "Проклятие крови",
			text = [=[В мире {red:draenor}Дренор{/red} чернокнижник {link:gul-dan}Гул'дан{/link} собрал вождей кланов и предложил им глоток крови демона {link:mannoroth}Маннорот{/link}а. Гром выпил первым, а другие — за ним. Кровь наполнила {link:orcs}орк{/link}ов страшной яростью и подчинила их воле Легиона. Когда {link:horde}Орда{/link} двинулась на {link:azeroth}Азерот{/link}, Гул'дан устроил так, чтобы Гром и его клан Песни Войны остались в Дреноре. Всю {link:second-war}Вторую войну{/link} они пропустили. После войны они прошли через {link:dark-portal}Темный портал{/link} и бились за него, пока его не разрушили, и застряли в землях людей.]=],
		},
		{
			title = "Оцепенение",
			text = [=[Много лет клан Песни Войны жил, скрываясь в глуши {link:lordaeron}Лордерона{/link}. Как и все {link:orcs}орк{/link}и, Гром был болен утратой демонической ярости. Но он боролся с оцепенением железной волей. Когда его разыскал молодой {link:thrall}Тралл{/link}, Гром увидел в нем надежду своего народа. Он вместе с ним освобождал орков из лагерей для пленных. {link:nak}Нак{/link}ануне {link:third-war}Третьей войны{/link} его схватили люди, и Тралл освободил его снова.]=],
		},
		{
			title = "Калимдор",
			text = [=[{link:orcs}Орки{/link} отплыли на запад, в {link:kalimdor}Калимдор{/link}. Там клан Песни Войны послали в чащи Ясеневого леса рубить деревья, и дело дошло до схваток с {link:night-elves}ночными эльфами{/link}. Защищать лес пришел полубог {link:cenarius}Кенарий{/link}. Отчаянно желая победы, Гром и его воины напились из источника, который {link:mannoroth}Маннорот{/link} осквернил своей кровью. Старое проклятие вернулось. В этой ярости Гром убил полубога. {link:thrall}Тралл{/link}, которому помогала {link:jaina-proudmoore}Джайна Праудмур{/link}, захватил друга и очистил его от ярости.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он первым из {link:orcs}орк{/link}ов выпил кровь демона {link:mannoroth}Маннорот{/link}а.
• Он удерживал {link:dark-portal}Темный портал{/link} против {link:alliance}Альянс{/link}а после Второй войны.
• Он противился оцепенению орков долгие годы, проведенные в укрытии.
• Он помогал вождю {link:thrall}Тралл{/link}у освобождать орков из лагерей.
• От его руки пал {link:cenarius}Кенарий{/link}, а затем и Маннорот.]=],
		},
		{
			title = "Судьба",
			text = [=[Гром и {link:thrall}Тралл{/link} вместе пошли в каньон, где ждал {link:mannoroth}Маннорот{/link}. Тралл пал под силой демона. Гром бросился вперед один, вогнал топор в грудь врага и убил его. Смерть демона освободила {link:orcs}орк{/link}ов от проклятия крови. Гром умер от ран на руках у друга. Его клан до сих пор рубит деревья Ясеневого леса во имя Орды, а ночные эльфы до сих пор дерутся с ним за каждое дерево.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "его вождь и друг" },
		{ id = "gul-dan", name = "Гул'дан", note = "дал ему кровь демона" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "такой же вождь клана" },
		{ id = "archimonde", name = "Архимонд", note = "хозяин демона, которого он убил" },
		{ id = "jaina-proudmoore", name = "Джайна Праудмур", note = "помогла освободить его" },
	},
})

Translate("ruRU", "gul-dan", {
	title = "Гул'дан",
	subtitle = "Предатель орков",
	allegiance = "Совет Теней · клан Бушующего Шторма",
	sections = {
		{
			title = "Обзор",
			text = [=[Гул'дан был первым {link:orcs}орк{/link}ом-чернокнижником и зодчим старой {link:horde}Орды{/link}. Некогда он был учеником шамана {link:ner-zhul}Нер'зула{/link}. Он продал свой народ {link:burning-legion}Пылающему Легиону{/link} в обмен на силу и отравил и свою расу, и свой мир. Он открыл {link:dark-portal}Темный портал{/link} вместе с Хранителем {link:medivh}Медивом{/link} и вел тайных хозяев Орды, {link:shadow-council}Совет Теней{/link}. В конце концов он предал и саму Орду.]=],
		},
		{
			title = "Значение",
			text = [=[Большую часть страданий {link:orcs}орк{/link}ов и народов, с которыми они воевали, можно возвести к его честолюбию. Его {link:fel-magic}магия Скверны{/link} вытянула жизнь из мира {red:draenor}Дренор{/red}. Кровь демона, которую он дал оркам, сделала их рабами собственной ярости. Его предательство стоило Орде {link:second-war}Второй войны{/link}.]=],
		},
		{
			title = "Совет Теней",
			text = [=[В Дреноре повелитель демонов {link:kil-jaeden}Кил'джеден{/link} искал слугу среди {link:orcs}орк{/link}ов. Когда {link:ner-zhul}Нер'зул{/link} начал сомневаться в демоне, Кил'джеден обратился к его ученику, который не сомневался вовсе. Кил'джеден обучил его искусству чародейства Скверны. Гул'дан основал {link:shadow-council}Совет Теней{/link}, круг чернокнижников, которые правили кланами из-за спины вождя-куклы Чернорука. Он предложил вождям кровь демона {link:mannoroth}Маннорота{/link}, и они выпили. Потом до него дошел голос из другого мира. Это был {link:medivh}Медив{/link}, и вместе они открыли {link:dark-portal}Темный портал{/link} в {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "Войны",
			text = [=[В конце {link:first-war}Первой войны{/link} Гул'дан попытался вырвать тайны Гробницы {link:sargeras}Саргерас{/link}а из умирающего разума Хранителя. Эта попытка повергла его в долгое оцепенение. Пока он спал, {link:orgrim-doomhammer}Оргрим Молот Рока{/link} убил вождя Чернорука и уничтожил большую часть {link:shadow-council}Совет{/link}а Теней. Проснувшись, Гул'дан купил себе жизнь обещанием нового оружия. Он и его чернокнижники подняли первых рыцарей смерти Орды. Но его верность была личиной. Пока Молот Рока осаждал столицу {link:lordaeron}Лордерона{/link}, Гул'дан забрал своих сторонников и уплыл искать Гробницу Саргераса под морем.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он основал {link:shadow-council}Совет Теней{/link} и правил Ордой через вождя Чернорука.
• Он дал вождям кровь демона {link:mannoroth}Маннорот{/link}а.
• Он открыл {link:dark-portal}Темный портал{/link} вместе с Хранителем {link:medivh}Медив{/link}ом.
• Он поднял первых рыцарей смерти Орды.
• Он бросил вождя Молота Рока у ворот столицы {link:lordaeron}Лордерон{/link}а.]=],
		},
		{
			title = "Судьба",
			text = [=[Гул'дан поднял Гробницу {link:sargeras}Саргерас{/link}а из глубин Великого моря и вошел в нее, надеясь завладеть силой бога. Демоны, которые ее охраняли, разорвали его на куски. Воины, которых Молот Рока послал покарать его измену, перебили его сторонников. Без них {link:horde}Орда{/link} не смогла удержать осаду, и ее отбросили к поражению. Череп чернокнижника пережил его и хранил собственную темную силу, пока не был уничтожен в {link:third-war}Третью войну{/link}.]=],
		},
	},
	bonds = {
		{ id = "ner-zhul", name = "Нер'зул", note = "его первый учитель" },
		{ id = "medivh", name = "Медив", note = "открыл с ним Темный портал" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "вождь, которого он предал" },
		{ id = "grom-hellscream", name = "Гром Адский Крик", note = "первым выпил кровь, которую он дал" },
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "забрал силу его черепа" },
	},
})

Translate("ruRU", "ner-zhul", {
	title = "Нер'зул",
	subtitle = "Старейший шаман клана Призрачной Луны",
	allegiance = "Клан Призрачной Луны · Плеть",
	sections = {
		{
			title = "Обзор",
			text = [=[Нер'зул был старейшим шаманом клана Призрачной Луны и самым почитаемым духовным вождем {link:orcs}орк{/link}ов мира {red:draenor}Дренор{/red}. Повелитель демонов {link:kil-jaeden}Кил'джеден{/link} обманул его и с его помощью обратил орков против дренеев. Позже Нер'зул разорвал собственный мир на части, пытаясь из него бежать. Попав в плен к демонам, он был превращен в {red:lich-king}Короля-лича{/red}, хозяина {link:scourge}Плети{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Нер'зул принес гибель дважды. Как шаман, он открыл сердца своего народа {link:burning-legion}Пылающему Легиону{/link}. Как Король-лич, он наслал чуму нежити на {link:lordaeron}Лордерон{/link}. {link:third-war}Третья война{/link} и мертвые земли севера — его дело не меньше, чем чье-либо еще.]=],
		},
		{
			title = "Обманщик",
			text = [=[В старые дни Дренора {link:orcs}орк{/link}и жили кланами охотников и шаманов. Нер'зул говорил среди них от имени духов. Потом к нему пришел {link:kil-jaeden}Кил'джеден{/link} в облике духа предков и нашептал, что мирные дренеи замышляют зло против орков. Нер'зул поверил ему и повел свой народ на войну. Лишь позже он увидел правду, и когда он отказался идти дальше, Кил'джеден обратился вместо него к его ученику, {link:gul-dan}Гул'дану{/link}. Старого шамана отбросили прочь, и он жил в позоре, пока {link:horde}Орда{/link} шла на {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "Раскол мира",
			text = [=[После {link:second-war}Второй войны{/link} {link:orcs}орк{/link}и, которые остались в Дреноре, собрались вокруг старого шамана. Он вновь открыл {link:dark-portal}Темный портал{/link} и послал воинов украсть в {link:azeroth}Азерот{/link}е могучие реликвии, собираясь открыть для своего народа врата в новые миры. {link:alliance}Альянс{/link} послал через Портал войско, чтобы остановить его. Нер'зул все равно открыл свои врата. Их силы разорвали Дренор на части, а он бежал через разлом со своими сторонниками.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он вел {link:orcs}орк{/link}ов как их величайший шаман.
• Обманутый демоном {link:kil-jaeden}Кил'джеден{/link}ом, он повел кланы против дренеев.
• Он вновь открыл {link:dark-portal}Темный портал{/link} после Второй войны.
• Он расколол Дренор своими вратами.
• Как Король-лич, он поднял {link:scourge}Плеть{/link} и наслал чуму на {link:lordaeron}Лордерон{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[За разломом его ждал {link:kil-jaeden}Кил'джеден{/link}. Демон сорвал плоть с тела шамана и заключил его дух в доспехи и шлем. Он запечатал пленника в глыбе льда и швырнул ее в {link:azeroth}Азерот{/link}. Она упала на ледник Ледяная Корона в {red:northrend}Нордсколе{/red}, и там шаман стал Королем-личом. С Ледяного Трона он поднял {link:scourge}Плеть{/link}. Он призвал к себе на службу некроманта {link:kel-thuzad}Кел'Тузада{/link} и послал чуму на юг. {link:nak}Нак{/link}онец через рунический клинок, {red:frostmourne}Ледяную Скорбь{/red}, он завладел принцем {link:arthas-menethil}Артасом Менетилом{/link}. Когда его сила пошла на убыль, он призвал принца к леднику Ледяная Корона, и тот надел его шлем. Теперь Нер'зул и Артас — одно, и Король-лич правит на севере.]=],
		},
	},
	bonds = {
		{ id = "gul-dan", name = "Гул'дан", note = "его ученик, занявший его место" },
		{ id = "arthas-menethil", name = "Артас Менетил", note = "принц, которым он завладел и с которым слился" },
		{ id = "kel-thuzad", name = "Кел'Тузад", note = "его слуга" },
		{ id = "grom-hellscream", name = "Гром Адский Крик", note = "вождь клана в его Орде" },
	},
})

Translate("ruRU", "archimonde", {
	title = "Архимонд",
	subtitle = "Осквернитель",
	allegiance = "Пылающий Легион",
	sections = {
		{
			title = "Обзор",
			text = [=[Архимонд {link:razelikh-the-defiler}Осквернитель{/link} был одним из великих владык {link:burning-legion}Пылающего Легиона{/link} и уступал только его темному хозяину, {link:sargeras}Саргерасу{/link}. Некогда он был вождем эредаров, гордого народа иного мира, пока Саргерас не предложил им силу и он не согласился. Он вел войны Легиона в бесчисленных мирах. В {link:azeroth}Азероте{/link} он подошел ближе любого демона до него к тому, чтобы пожрать мир, и погиб у подножия Мирового Древа.]=],
		},
		{
			title = "Значение",
			text = [=[Его вторжение в {link:third-war}Третью войну{/link} было величайшим натиском демонов, какой мир знал со времен {link:war-of-the-ancients}Войны древних{/link}. Его поражение у {link:mount-hyjal}горы Хиджал{/link} выковало непрочный мир между {link:orcs}орками{/link}, {link:humans}людьми{/link} и {link:night-elves}ночными эльфами{/link}, и этот мир с тех пор определяет судьбу {link:kalimdor}Калимдора{/link}.]=],
		},
		{
			title = "Эредары",
			text = [=[Давным-давно эредарами правили трое вождей: Архимонд, {link:kil-jaeden}Кил'джеден{/link} и Велен. {link:sargeras}Саргерас{/link} пришел к ним и предложил знание и мощь. Архимонд и Кил'джеден согласились и были искажены в демонов. Велен отказался и бежал со своими сторонниками. Архимонд стал одним из величайших полководцев темного титана. В Войну древних, десять тысяч лет назад, Легион пришел в {link:azeroth}Азерот{/link} через {link:well-of-eternity}Источник Вечности{/link}. Его отбросили, когда Источник был уничтожен.]=],
		},
		{
			title = "Третья война",
			text = [=[Легион вернулся много веков спустя. Когда {link:scourge}Плеть{/link} разорила {link:lordaeron}Лордерон{/link}, лич {link:kel-thuzad}Кел'Тузад{/link} с помощью книги заклинаний, которую оставил {link:medivh}Медив{/link}, призвал владыку демонов в город {link:dalaran}Даларан{/link}. Архимонд разрушил {link:city-of-dalaran}город магов{/link} одним ударом своей силы. Затем он повел Легион в {link:kalimdor}Калимдор{/link}, где последние воды {link:well-of-eternity}Источника Вечности{/link} лежали под Мировым Древом, {link:nordrassil}Нордрассилом{/link}. Он хотел вытянуть его силу и поглотить мир.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он принял то, что предложил {link:sargeras}Саргерас{/link}, и стал владыкой Легиона.
• Он воевал против {link:azeroth}Азерот{/link}а в Войну древних.
• Его призвал в {link:dalaran}Даларан{/link} лич {link:kel-thuzad}Кел'Тузад{/link}, и он разрушил город.
• Он пошел на гору Хиджал, чтобы вытянуть силу древа {link:nordrassil}Нордрассил{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[В {link:battle-of-mount-hyjal}Битве у горы Хиджал{/link} склоны горы, сколько могли, удерживали {link:orcs}орк{/link}и, которых вел {link:thrall}Тралл{/link}, люди, которых вела {link:jaina-proudmoore}Джайна Праудмур{/link}, и ночные эльфы, которых вели {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link} и {link:malfurion-stormrage}Малфурион Ярость Бури{/link}. {link:nak}Нак{/link}онец Архимонд поднялся к Мировому Древу. Малфурион протрубил в Рог Кенария, и несметное войско духов древних облепило владыку демонов и уничтожило его в великом взрыве. Сила древа {link:nordrassil}Нордрассил{/link} была истрачена, и ночные эльфы потеряли бессмертие. Но вторжение Легиона было сломлено. Его демоны до сих пор держатся в порченых чащах {link:felwood}Оскверненного леса{/link}, и его тень не ушла из мира.]=],
		},
	},
	bonds = {
		{ id = "kel-thuzad", name = "Кел'Тузад", note = "призвал его в Азерот" },
		{ id = "malfurion-stormrage", name = "Малфурион Ярость Бури", note = "добился его гибели" },
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "враг в Третью войну" },
		{ id = "queen-azshara", name = "Королева Азшара", note = "открыла путь Легиону древности" },
		{ id = "grom-hellscream", name = "Гром Адский Крик", note = "убил его слугу, демона Маннорота" },
	},
})

Translate("ruRU", "illidan-stormrage", {
	title = "Иллидан Ярость Бури",
	subtitle = "Предатель",
	allegiance = "Неизвестно (прежде сопротивление калдореи)",
	aliases = { "Иллидан", "Предатель" },
	sections = {
		{
			title = "Обзор",
			text = [=[Иллидан Ярость Бури был чародеем {link:night-elves}ночных эльфов{/link} древнего мира, братом-близнецом друида {link:malfurion-stormrage}Малфуриона Ярости Бури{/link} и его соперником в любви к жрице {link:tyrande-whisperwind}Тиранде Шелест Ветра{/link}. Он сражался с {link:burning-legion}Пылающим Легионом{/link}, и он же служил ему. Он провел в заточении десять тысяч лет и был освобожден в {link:third-war}Третью войну{/link}. Одни называют его героем, многие — изменником. Собственный народ прозвал его Предателем.]=],
		},
		{
			title = "Значение",
			text = [=[Его решения в равной мере спасали мир и грозили ему. В древности он принес воды {link:well-of-eternity}Источника Вечности{/link} на {link:mount-hyjal}гору Хиджал{/link}, где они и теперь лежат под древом {link:nordrassil}Нордрассил{/link}. В Третью войну он убил владыку Легиона и забрал его силу себе.]=],
		},
		{
			title = "Война древних",
			text = [=[Иллидан родился с янтарными глазами — знак, который, как говорили, предвещает величие. Его влекла {link:arcane-magic}тайная магия{/link}, как его брата влек путь, которому учил {link:cenarius}Кенарий{/link}. В {link:war-of-the-ancients}Войну древних{/link} он сражался рядом с ночными эльфами против их правительницы, {link:queen-azshara}королевы Азшары{/link}, и ее союзников-демонов. Но в нем росли зависть к брату и жажда силы, и наконец он пошел к самому хозяину Легиона. {link:sargeras}Саргерас{/link} выжег ему глаза и дал новое зрение. Когда {link:well-of-eternity}Источник Вечности{/link} был уничтожен, Иллидан вылил похищенные склянки с его водой в озеро на вершине горы Хиджал и создал новый Источник. {link:malfurion-stormrage}Малфурион{/link} счел это преступлением. Он велел заковать брата под землей, а стеречь его стала тюремщица Майев Песнь Теней.]=],
		},
		{
			title = "Третья война",
			text = [=[Десять тысяч лет спустя {link:scourge}Плеть{/link} и Легион пришли в {link:kalimdor}Калимдор{/link}. Вопреки закону своего народа {link:tyrande-whisperwind}Тиранда{/link} освободила узника, чтобы он помог. В лесу, который теперь зовут {link:felwood}Оскверненным{/link}, он поглотил Череп, который оставил после себя {link:gul-dan}Гул'дан{/link}, принял облик демона и убил повелителя ужаса {link:tichondrius}Тикондрус{/link}а. {link:malfurion-stormrage}Малфурион{/link} изгнал его из лесов ночных эльфов.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он сражался против королевы Азшары в Войну древних.
• Он создал новый {link:well-of-eternity}Источник Вечности{/link} на вершине горы Хиджал.
• Он поглотил Череп чернокнижника {link:gul-dan}Гул'дан{/link}а и убил демона {link:tichondrius}Тикондрус{/link}а.
• После Третьей войны он поднял из глубин наг, чтобы они служили ему.]=],
		},
		{
			title = "Судьба",
			text = [=[После изгнания Иллидан собрал {link:naga}наг{/link} и искал Гробницу {link:sargeras}Саргерас{/link}а под морем. За ним гнались Майев, его брат и {link:tyrande-whisperwind}Тиранда{/link}, и он ушел от всех. Позже он двинулся на {red:northrend}Нордскол{/red}, чтобы ударить по {red:lich-king}Королю-личу{/red}. У ледника Ледяная Корона он сразился с принцем {link:arthas-menethil}Артасом Менетилом{/link} и был побежден. Он бежал с уцелевшими сторонниками. Куда он ушел после этого, не скажет ни одна летопись королевств.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Малфурион Ярость Бури", note = "его брат-близнец" },
		{ id = "tyrande-whisperwind", name = "Тиранда Шелест Ветра", note = "любовь, которую он потерял" },
		{ id = "queen-azshara", name = "Королева Азшара", note = "давний враг" },
		{ id = "arthas-menethil", name = "Артас Менетил", note = "победил его у ледника Ледяная Корона" },
		{ id = "gul-dan", name = "Гул'дан", note = "чей череп он поглотил" },
	},
})

Translate("ruRU", "malfurion-stormrage", {
	title = "Малфурион Ярость Бури",
	subtitle = "Первый друид",
	allegiance = "Ночные эльфы · Круг Кенария",
	aliases = { "Малфурион" },
	sections = {
		{
			title = "Обзор",
			text = [=[Малфурион Ярость Бури был первым друидом {link:night-elves}ночных эльфов{/link}, учеником полубога {link:cenarius}Кенария{/link} и братом-близнецом чародея {link:illidan-stormrage}Иллидана Ярости Бури{/link}. Он вел борьбу против {link:burning-legion}Пылающего Легиона{/link} в {link:war-of-the-ancients}Войну древних{/link} и снова — в {link:third-war}Третью войну{/link}. Он возлюбленный жрицы {link:tyrande-whisperwind}Тиранды Шелест Ветра{/link}. Теперь он спит в {link:emerald-dream}Изумрудном Сне{/link}, и его народ ждет, когда он проснется.]=],
		},
		{
			title = "Значение",
			text = [=[Малфурион спас мир дважды. В древности он уничтожил {link:well-of-eternity}Источник Вечности{/link}, чтобы закрыть дверь перед Легионом. Десять тысяч лет спустя у подножия Мирового Древа он уничтожил владыку демонов {link:archimonde}Архимонда{/link}. Друиды всех земель идут путем, по которому он прошел первым.]=],
		},
		{
			title = "Война древних",
			text = [=[Его влек живой мир, пока его брат изучал тайную магию. {link:cenarius}Кенарий{/link} взял его в ученики и научил придавать облик силам природы. Когда {link:queen-azshara}королева Азшара{/link} и ее высокорожденные привели Легион в мир, Малфурион примкнул к сопротивлению. Он понял, что остановить Легион можно, только уничтожив сам {link:well-of-eternity}Источник Вечности{/link}. Его удар по Источнику вызвал {link:great-sundering}Великий Раскол{/link}, который разбил землю и утопил столицу королевы. Когда {link:illidan-stormrage}Иллидан{/link} создал новый Источник на {link:mount-hyjal}горе Хиджал{/link}, Малфурион велел заточить брата. С помощью великих драконов уцелевшие посадили над новым Источником древо {link:nordrassil}Нордрассил{/link}. Затем Малфурион и его друиды п{link:ogres}огр{/link}узились в долгий сон в Изумрудном Сне.]=],
		},
		{
			title = "Третья война",
			text = [=[Когда Легион вернулся, {link:tyrande-whisperwind}Тиранда{/link} разбудила друидов. Малфурион вывел их обратно в мир и помог отстоять от демонов леса {link:ashenvale}Ясеневого леса{/link}. Против его воли Тиранда освободила его брата, и Малфурион опоздал помешать тому, чтобы {link:illidan-stormrage}Иллидан{/link} взял силу демона. Он изгнал брата и вернулся к обороне горы Хиджал. Там он стоял рядом с {link:orcs}орк{/link}ами, которых вел {link:thrall}Тралл{/link}, и с людьми, которых вела {link:jaina-proudmoore}Джайна Праудмур{/link}. Когда {link:archimonde}Архимонд{/link} добрался до древа {link:nordrassil}Нордрассил{/link}, Малфурион протрубил в Рог Кенария. Духи древних уничтожили владыку демонов, и мир был спасен.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он постиг пути природы, которым учил {link:cenarius}Кенарий{/link}, и стал первым друидом.
• Он уничтожил {link:well-of-eternity}Источник Вечности{/link} и закончил Войну древних.
• Он заточил своего брата под землей.
• Он вел друидов против Легиона в Третью войну.
• Его волей {link:archimonde}Архимонд{/link} был уничтожен в Битве у горы Хиджал.]=],
		},
		{
			title = "Судьба",
			text = [=[После войны Малфурион гнался за братом через море, а потом отпустил его. Он вернулся в {link:emerald-dream}Изумрудный Сон{/link} и с тех пор не просыпался. Пока его нет, друидов {link:darnassus}Дарнасса{/link} ведет верховный друид {link:fandral-staghelm}Фэндрал Олений Шлем{/link}, а ночные эльфы посадили новое Мировое Древо, {link:teldrassil}Тельдрассил{/link}. {link:tyrande-whisperwind}Тиранда{/link} правит и ждет.]=],
		},
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "его брат-близнец" },
		{ id = "tyrande-whisperwind", name = "Тиранда Шелест Ветра", note = "его возлюбленная" },
		{ id = "archimonde", name = "Архимонд", note = "демон, которого он уничтожил" },
		{ id = "queen-azshara", name = "Королева Азшара", note = "королева, против которой он сражался" },
		{ id = "fandral-staghelm", name = "Фэндрал Олений Шлем", note = "ведет друидов вместо него" },
	},
})

Translate("ruRU", "queen-azshara", {
	title = "Королева Азшара",
	subtitle = "Королева высокорожденных",
	allegiance = "Высокорожденные · Наги",
	sections = {
		{
			title = "Обзор",
			text = [=[Королева Азшара правила древней империей {link:night-elves}ночных эльфов{/link} на вершине ее славы. Она была самой прекрасной и самой могущественной в своем народе, и народ ее обожал. Из своего дворца в Зин-Азшари у {link:well-of-eternity}Источника Вечности{/link} она вела высокорожденных в изучении {link:arcane-magic}тайной магии{/link}. В своей гордыне она открыла мир {link:burning-legion}Пылающему Легиону{/link}, и ее империя утонула в море.]=],
		},
		{
			title = "Значение",
			text = [=[Ее предательство начало {link:war-of-the-ancients}Войну древних{/link} и кончилось {link:great-sundering}Великим Расколом{/link}. Разбитые очертания {link:kalimdor}Калимдора{/link} и {link:eastern-kingdoms}Восточных королевств{/link} — ее наследие. Ее же наследие, быть может, и {link:naga}наги{/link}, которые теперь поднимаются из волн.]=],
		},
		{
			title = "Королева высокорожденных",
			text = [=[Народ называл в ее честь города и горы. Высокорожденные, знатная каста ее двора, служили ей жрецами и чародеями. При ее правлении они черпали из Источника Вечности все глубже. Их заклинания вышли за пределы мира и привлекли взор темного титана {link:sargeras}Саргераса{/link}. Повелитель демонов шептал королеве, и она слушала. Она поверила, что мир надо очистить от всех низших народов и что Саргерас это сделает.]=],
		},
		{
			title = "Война древних",
			text = [=[{link:azshara}Азшара{/link} и ее высокорожденные открыли портал внутри Источника, и через него хлынули демоны Легиона. В этом деле ей служил ее советник Ксавий. {link:night-elves}Ночные эльфы{/link}, которые остались свободными, восстали против своей королевы; их вели {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link} и лорд Кур'талос Гребень Ворона. Пока бушевала война, высокорожденные трудились над тем, чтобы привести в мир самого хозяина Легиона. Их остановило только уничтожение Источника. Его крушение разорвало землю, и море хлынуло на Зин-Азшари.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она правила ночными эльфами на вершине их могущества.
• Она вела высокорожденных в пользовании Источником Вечности.
• Она открыла Пылающему Легиону путь в {link:azeroth}Азерот{/link}.
• Она стремилась привести в мир самого титана {link:sargeras}Саргерас{/link}а.]=],
		},
		{
			title = "Судьба",
			text = [=[Когда Источник рухнул, Азшара и ее высокорожденные исчезли под волнами. Предания ночных эльфов говорят, что они не умерли, а изменились, и что змееподобные наги — это то, чем они стали. В эти дни наги вернулись к берегам и совершают набеги на побережья {link:kalimdor}Калимдор{/link}а и других земель. Некоторые из них говорят о своей древней королеве так, будто она еще жива. В краю, который носит ее имя, в {link:azshara}Азшаре{/link}, остались только руины ее империи.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Ни одна запись смертных не говорит, жива ли еще {link:azshara}Азшара{/link} под морем и чем она стала.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Малфурион Ярость Бури", note = "вел мятеж против нее" },
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "сражался с ее двором" },
		{ id = "archimonde", name = "Архимонд", note = "владыка Легиона, которому она служила" },
		{ id = "tyrande-whisperwind", name = "Тиранда Шелест Ветра", note = "вела мятеж против нее" },
	},
})

Translate("ruRU", "deathwing", {
	title = "Смертокрыл",
	subtitle = "Разрушитель",
	allegiance = "Род черных драконов",
	aliases = { "Нелтарион" },
	sections = {
		{
			title = "Обзор",
			text = [=[Некогда Смертокрыл звался Нелтарионом и был Стражем Земли, Аспектом рода черных драконов. Ему было поручено стеречь глубины мира. Его охватило безумие, и он предал другие роды драконов в {link:war-of-the-ancients}Войну древних{/link}. С тех пор он строит козни против всех народов {link:azeroth}Азерота{/link}. Его имя означает гибель и для драконов, и для смертных.]=],
		},
		{
			title = "Значение",
			text = [=[Измена Смертокрыла едва не уничтожила роды драконов. Его вмешательство во {link:second-war}Вторую войну{/link} дало {link:horde}Орде{/link} ее драконов. Его черный выводок до сих пор обитает в {link:blackrock-mountain}Черной горе{/link} и в других темных местах мира.]=],
		},
		{
			title = "Страж Земли",
			text = [=[В древние дни пять великих драконов были избраны Аспектами, чтобы стеречь мир. Дракону Нелтариону дали власть над землей и ее глубинами. Что-то шептало ему из-под толщи камня, и со временем его разум помутился. В Войну древних он выковал большой золотой диск, Душу Дракона. Он убедил других Аспектов отдать диску часть своей силы и сказал им, что это отбросит {link:burning-legion}Пылающий Легион{/link}. Вместо этого он обратил диск против них. Сила вещи была так велика, что его тело начало рваться на части, и к его шкуре прикрепили металлические пластины, чтобы оно не распалось. Он бежал, а Душа Дракона была утрачена.]=],
		},
		{
			title = "Вторая война",
			text = [=[Смертокрыл давно ходит среди смертных в человеческом обличье, как вельможа, вхожий ко дворам королей. Летописи говорят, что он сеял раздор всюду, где мог. Во Вторую войну Душа Дракона попала в руки {link:orcs}орк{/link}ов клана Драконьей Пасти. С ее помощью они пленили Аспекта красных драконов, {link:alexstrasza}Алекстразу{/link}, и держали ее под горой {link:grim-batol}Грим Батол{/link}. Ее детенышей растили как боевых ездовых зверей для Орды.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он предал Аспектов с помощью Души Дракона в Войну древних.
• Он тайно ходил при дворах людей.
• Он допустил, чтобы Душа Дракона досталась клану Драконьей Пасти.
• Он пытался украсть яйца красных драконов из {link:grim-batol}Грим Батол{/link}а.]=],
		},
		{
			title = "Судьба",
			text = [=[После Второй войны {link:dragonmaw-clan}клан Драконьей Пасти{/link} все еще держал в плену королеву красных драконов в {link:grim-batol}Грим Батол{/link}е. Смертокрыл пришел за ее яйцами, желая возродить собственный род. Небольшой отряд героев и драконов освободил красную королеву, и Душа Дракона была уничтожена. Смертокрыла, пришедшего в ярость, прогнали. Куда он ушел, не знает никто. Гору Грим Батол в {link:wetlands}Болотине{/link} {link:dwarves}дворф{/link}ы обходят стороной по сей день. Его дети и его род черных драконов все еще бродят по миру.]=],
		},
	},
	bonds = {
		{ id = "alexstrasza", name = "Алекстраза", note = "Аспект, которую он помог поработить" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "вождь Орды, которая воспользовалась его даром" },
		{ id = "queen-azshara", name = "Королева Азшара", note = "союзница Легиона, с которым он будто бы сражался" },
	},
})

Translate("ruRU", "kel-thuzad", {
	title = "Кел'Тузад",
	subtitle = "Основатель Культа Проклятых",
	allegiance = "Плеть · Культ Проклятых (прежде Кирин-Тор)",
	sections = {
		{
			title = "Обзор",
			text = [=[Некогда Кел'Тузад был верховным магом {link:dalaran}Даларана{/link} и входил в правящий совет {link:kirin-tor}Кирин-Тора{/link}. Он обратился к запретному искусству некромантии, присягнул {red:lich-king}Королю-личу{/red} и основал {link:cult-of-the-damned}Культ Проклятых{/link}. Он разнес чуму, которая погубила {link:lordaeron}Лордерон{/link}. Убитый принцем {link:arthas-menethil}Артасом Менетилом{/link}, он восстал вновь как лич. Теперь он повелевает {link:scourge}Плетью{/link} в Лордероне от имени своего хозяина.]=],
		},
		{
			title = "Значение",
			text = [=[Без него чума нежити, быть может, никогда не дошла бы до народа {link:lordaeron}Лордерон{/link}а. Он был голосом Короля-лича среди живых и открыл {link:burning-legion}Пылающему Легиону{/link} путь назад в {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "Верховный маг",
			text = [=[Кел'Тузад был одним из величайших магов {link:dalaran}Даларан{/link}а, но считал, что его собратья слишком робки в своих изысканиях. Он начал углубляться в темное искусство некромантии. Когда совет это запретил, он не остановился. Его звал голос из {red:northrend}Нордскола{/red}. Он откликнулся, отправился на ледяной север и присягнул Королю-личу. Хозяин обещал ему вечную жизнь.]=],
		},
		{
			title = "Культ Проклятых",
			text = [=[Кел'Тузад вернулся в {link:lordaeron}Лордерон{/link} и говорил бедным и усталым о новом обществе, где все будут равны и никто не умрет. Тысячи вступили в его {link:cult-of-the-damned}Культ Проклятых{/link}. Через них он заразил зерно северных житниц чумой, которая обращала живых в нежить. Когда {link:arthas-menethil}Артас{/link} пришел на север бороться с чумой, он нашел некроманта в {link:ruins-of-andorhal}Андорал{/link}е и убил его. Но дух некроманта остался и шептал принцу, пока тот шел к своему падению.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он изучал некромантию наперекор {link:kirin-tor}Кирин-Тор{/link}у.
• Он присягнул Королю-личу в Нордсколе.
• Он основал {link:cult-of-the-damned}Культ Проклятых{/link}.
• Он разнес чуму нежити через зерно {link:lordaeron}Лордерон{/link}а.
• Он призвал в {link:dalaran}Даларан{/link} владыку демонов {link:archimonde}Архимонда{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[Когда {link:arthas-menethil}Артас{/link} стал слугой Короля-лича, он отвез останки некроманта в {link:quel-thalas}Кель'Талас{/link}. Там, в водах Солнечного Колодца, Кел'Тузад возродился как лич. С помощью книги заклинаний, которую оставил {link:medivh}Медив{/link}, он призвал в {link:dalaran}Даларан{/link} владыку демонов, и {link:archimonde}Архимонд{/link} обратил город в руины. Когда Артас вернулся в Нордскол, Кел'Тузад остался править {link:scourge}Плеть{/link}ю в {link:lordaeron}Лордерон{/link}е. Он правит ею и поныне. Великий некрополь {red:naxxramas}Наксрамас{/red} парит над Чумными землями, а его культисты держат свою школу темной науки в старом замке {link:caer-darrow}Каэр Дарроу{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Артас Менетил", note = "его убийца, потом его господин" },
		{ id = "ner-zhul", name = "Нер'зул", note = "Король-лич, которому он присягнул" },
		{ id = "archimonde", name = "Архимонд", note = "демон, которого он призвал" },
		{ id = "terenas-menethil", name = "Теренас Менетил", note = "чей прах уступил место его костям" },
	},
})

Translate("ruRU", "jaina-proudmoore", {
	title = "Джайна Праудмур",
	subtitle = "Правительница Терамора",
	found = "Цитадель, Остров Терамор, в Пылевых топях",
	hint = "Ищите владычицу Терамора в башне ее островной цитадели.",
	allegiance = "Терамор · Альянс · Кирин-Тор",
	aliases = { "Джайна", "леди Джайна Праудмур", "леди Праудмур" },
	sections = {
		{
			title = "Обзор",
			text = [=[Леди Джайна Праудмур правит {link:theramore-isle}Терамором{/link}, островной твердыней {link:alliance}Альянса{/link} на восточном берегу {link:kalimdor}Калимдора{/link}. Она дочь лорда-адмирала {link:kul-tiras}Кул Тираса{/link} {link:daelin-proudmoore}Делина Праудмура{/link} и чародейка, которую обучил в {link:dalaran}Даларане{/link} {link:kirin-tor}Кирин-Тор{/link}. Она шла рядом с принцем {link:arthas-menethil}Артасом Менетилом{/link} в дни чумы и рассталась с ним до его падения. Она увела уцелевших жителей севера за море и заключила с {link:horde}Ордой{/link} мир, какой до нее никто не считал возможным.]=],
		},
		{
			title = "Значение",
			text = [=[Джайна — мост между старыми врагами. Она стояла рядом с вождем {link:thrall}Траллом{/link} в {link:battle-of-mount-hyjal}Битве у горы Хиджал{/link} и хранит верность ему до сих пор. Этот мир стоил ей отца. Он хрупок, и многие с обеих сторон хотели бы видеть его разрушенным.]=],
		},
		{
			title = "Чума",
			text = [=[В юности Джайна изучала магию в {link:dalaran}Даларан{/link}е у верховного мага {link:brother-anton}Антон{/link}идаса и выказала редкие дарования. Когда странная чума пошла по северным пашням {link:lordaeron}Лордерона{/link}, она отправилась с принцем искать ее источник. Вместе они раскрыли {link:cult-of-the-damned}Культ Проклятых{/link} и зараженное зерно. В Стратхольме {link:arthas-menethil}Артас{/link} приказал перебить жителей города прежде, чем они восстанут нежитью. Джайна отказалась в этом участвовать и оставила его там. {link:culling-of-stratholme}Очищение Стратхольма{/link} свершилось без нее.]=],
		},
		{
			title = "Путь на запад",
			text = [=[Таинственный пророк убеждал вождей востока плыть на запад, за море. Джайна вняла ему, когда другие не вняли, и увела уцелевших жителей {link:lordaeron}Лордерон{/link}а в {link:kalimdor}Калимдор{/link}. Там она встретила вождя {link:thrall}Тралл{/link}а и его {link:orcs}орк{/link}ов, старых врагов ее народа. {link:jammal-an-the-prophet}Пророк{/link} свел их вместе против большего врага, и у горы Хиджал человек, орк и {link:night-elves}ночной эльф{/link} сражались бок о бок, пока {link:archimonde}Архимонд{/link} не был уничтожен.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она изучала магию среди магов {link:kirin-tor}Кирин-Тор{/link}а в {link:dalaran}Даларан{/link}е.
• Она шла по следу чумы вместе с принцем {link:arthas-menethil}Артас{/link}ом и отказалась от Очищения Стратхольма.
• Она увела уцелевших жителей {link:lordaeron}Лордерон{/link}а на запад, в {link:kalimdor}Калимдор{/link}.
• Она сражалась у горы Хиджал рядом с вождем {link:thrall}Тралл{/link}ом и ночными эльфами.
• Она основала {link:theramore-isle}Терамор{/link} и заключила мир с Ордой.]=],
		},
		{
			title = "Терамор",
			text = [=[После войны Джайна возвела {link:theramore-isle}Терамор{/link} на острове у берегов {link:dustwallow-marsh}Пылевых топей{/link}. Потом в {link:kalimdor}Калимдор{/link} с большим флотом пришел ее отец. {link:daelin-proudmoore}Делин{/link} не желал принять мир с {link:orcs}орк{/link}ами и пошел на них войной. Джайна не смогла уговорить его остановиться. Она не дала ему разрушить мир и отступила в сторону, пока {link:horde}Орда{/link} защищалась. Делин был убит в бою перед стенами Терамора. Его дочь скорбит, а моряки, которые шли за ним, ее не простили.]=],
		},
		{
			title = "Наши дни",
			text = [=[Джайна правит {link:theramore-isle}Терамор{/link}ом из его цитадели. Город — приют для людей потерянного севера и ворота {link:alliance}Альянс{/link}а в {link:kalimdor}Калимдор{/link}. Она хранит мир с вождем {link:thrall}Тралл{/link}ом, как может, пока солдаты обеих сторон сталкиваются в глуши.]=],
		},
	},
	chapters = {
		{
			title = "Пропавший посол",
			hint = "Пройдите по следу пропавшего посла до Терамора.",
			text = [=[След похищенного посланника вел из {link:stormwind-city}Штормграда{/link} в {link:menethil-harbor}Гавань Менетилов{/link}, а оттуда — через море в {link:dustwallow-marsh}Пылевые топи{/link}. В его конце стоял рядовой {link:private-hendel}Хендель{/link}, солдат {link:theramore-isle}Терамор{/link}а, который продался {link:defias-brotherhood}Братству Справедливости{/link}. Когда его разоблачили, он обнажил клинок. Джайна и ее стража пришли взять его живым, ибо мертвый изменник ничего не расскажет. Владычица Терамора тихо поблагодарила тех, кто вывел правду на свет. Открыто благодарить их она не могла. Что знает Хендель о пропавшем короле Штормграда — это дело ее дознавателей.]=],
		},
	},
	mentions = {
		{ text = "Пропавший посол" },
		{ text = "Пропавший посол" },
	},
	bonds = {
		{ id = "daelin-proudmoore", name = "Делин Праудмур", note = "ее отец" },
		{ id = "arthas-menethil", name = "Артас Менетил", note = "ее спутник и ее утраченная любовь" },
		{ id = "thrall", name = "Тралл", note = "ее союзник в мире" },
		{ id = "aegwynn", name = "Эгвин", note = "как говорят, давала ей советы" },
		{ id = "tapoke-slim-jahn", name = "Тапоке «Тощий» Джан", note = "помогал заговору, который раскрыла ее стража" },
	},
})

Translate("ruRU", "khadgar", {
	title = "Кадгар",
	subtitle = "Ученик последнего Хранителя",
	allegiance = "Кирин-Тор · Альянс Лордерона",
	sections = {
		{
			title = "Обзор",
			text = [=[Кадгар был молодым магом {link:dalaran}Даларана{/link}, которого {link:kirin-tor}Кирин-Тор{/link} послал в ученики к последнему Хранителю Тирисфаля, {link:medivh}Медиву{/link}. Он первым увидел, что {link:orcs}орк{/link}ов в {link:azeroth}Азерот{/link} привел сам Хранитель. Он сражался в {link:first-war}Первую войну{/link} и во {link:second-war}Вторую войну{/link} и стал одним из великих верховных магов своего века. Давным-давно он прошел через {link:dark-portal}Темный портал{/link} и не вернулся.]=],
		},
		{
			title = "Значение",
			text = [=[Кадгар вынес правду из {link:karazhan}Каражана{/link}. Без него {link:stormwind-city}Штормград{/link}, быть может, никогда не узнал бы, кто его истинный враг. Во Вторую войну он стоял рядом с главнокомандующим {link:anduin-lothar}Андуином Лотаром{/link} как один из вождей {link:alliance}Альянса{/link}, а в конце закрыл путь между мирами ценой собственного возвращения.]=],
		},
		{
			title = "Каражан",
			text = [=[Маги {link:dalaran}Даларан{/link}а давно хотели узнать тайны башни Хранителя. Они послали туда ученика и велели ему наблюдать. Хранитель принял его и учил. Вскоре Кадгар узнал, что его учителю свойственны долгое молчание, странные видения и тьма, о которой тот не желал говорить. Вместе с полуорчихой {link:garona}Гароной{/link}, которая пришла в башню посланницей {link:horde}Орды{/link}, он открыл, что {link:dark-portal}Темный портал{/link} отворил сам {link:medivh}Медив{/link}. Вдвоем они отнесли предостережение королю {link:llane-wrynn}Ллейну Ринну{/link}. Затем Кадгар поднялся в {link:karazhan}Каражан{/link} вместе с рыцарем {link:anduin-lothar}Лотар{/link}ом, чтобы встать против своего учителя. Медив был убит. В той битве молодой маг в один миг постарел на много лет и спустился из башни с лицом старика.]=],
		},
		{
			title = "Вторая война",
			text = [=[Кадгар ушел на север с рыцарем {link:anduin-lothar}Лотар{/link}ом и изгнанниками {link:stormwind-city}Штормград{/link}а. В {link:lordaeron}Лордероне{/link} он был одним из помощников защитника вместе с паладином {link:turalyon}Туралионом{/link}. Он бился с Ордой по всем северным королевствам и помог добиться ее поражения у {link:blackrock-mountain}Черной горы{/link}. Когда война была выиграна, {link:alliance}Альянс{/link} разрушил {link:dark-portal}Темный портал{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он был последним учеником Хранителя в {link:karazhan}Каражан{/link}е.
• Он открыл, какую роль {link:medivh}Медив{/link} сыграл в приходе {link:orcs}орк{/link}ов, и предупредил короля {link:llane-wrynn}Ллейн{/link}а.
• Он сражался рядом с рыцарем Андуином {link:anduin-lothar}Лотар{/link}ом, когда пал Медив.
• Он был одним из помощников главнокомандующего {link:alliance}Альянс{/link}а во Вторую войну.
• После войны он повел Альянс за {link:dark-portal}Темный портал{/link}.]=],
		},
		{
			title = "За Порталом",
			text = [=[Через несколько лет после Второй войны Портал открылся снова. Через него из мира {red:draenor}Дренор{/red} пришли {link:orcs}орк{/link}и, чтобы украсть реликвии силы; их послал старый шаман {link:ner-zhul}Нер'зул{/link}. {link:alliance}Альянс{/link} отправил за ними войско в родной мир орков. Вели его Кадгар и {link:turalyon}Туралион{/link}. Заклинания шамана разорвали Дренор на части. Чтобы разрушение не перекинулось на {link:azeroth}Азерот{/link}, вожди Альянса решили закрыть Портал с дальней стороны. Они знали, что не смогут вернуться домой. Портал умолк, и поход был потерян для своего народа.]=],
		},
		{
			title = "Судьба",
			text = [=[С тех пор как закрылся Портал, ни слова о нем не дошло до королевств. В {link:blasted-lands}Выжженных землях{/link} маги {link:kirin-tor}Кирин-Тор{/link}а несут стражу над разрушенными вратами из Крепости Стражей Пустоты, и они его не забыли.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Ни одна летопись королевств не говорит, что стало за Порталом с магом и его спутниками.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Медив", note = "его учитель" },
		{ id = "garona", name = "Гарона", note = "его союзница в Каражане" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "его командир" },
		{ id = "turalyon", name = "Туралион", note = "его спутник в двух войнах" },
		{ id = "ner-zhul", name = "Нер'зул", note = "его враг за Порталом" },
	},
})

Translate("ruRU", "turalyon", {
	title = "Туралион",
	subtitle = "Победитель во Второй войне",
	allegiance = "Рыцари Серебряной Длани · Альянс Лордерона",
	sections = {
		{
			title = "Обзор",
			text = [=[Туралион был молодым священником {link:holy-light}Света{/link}, который стал одним из первых паладинов ордена рыцарей Серебряной Длани. Во {link:second-war}Вторую войну{/link} он служил помощником главнокомандующего {link:anduin-lothar}Андуина Лотара{/link}. Когда его командир пал, Туралион принял начало над войском и выиграл войну. Потом он повел {link:alliance}Альянс{/link} за {link:dark-portal}Темный портал{/link} и не вернулся.]=],
		},
		{
			title = "Значение",
			text = [=[Именно Туралион обратил самый темный час {link:alliance}Альянс{/link}а в победу. Его натиск у {link:blackrock-mountain}Черной горы{/link} сломил старую {link:horde}Орду{/link}, и мир, который северные королевства знали целое поколение, был его даром.]=],
		},
		{
			title = "Серебряная Длань",
			text = [=[Туралион был священником церкви в {link:lordaeron}Лордероне{/link}, когда изгнанники {link:stormwind-city}Штормград{/link}а пришли на север. {link:anduin-lothar}Лотар{/link} увидел в нем силу и сделал его одним из своих помощников вместе с магом {link:khadgar}Кадгаром{/link}. Туралион сомневался в себе и в своей вере. И все же он был среди первых рыцарей, которых архиепископ {link:alonsus-faol}Алонсий Фаол{/link} научил владеть {link:holy-light}Свет{/link}ом в бою; с ним были {link:uther-the-lightbringer}Утер Светоносный{/link}, {link:tirion-fordring}Тирион Фордринг{/link} и еще несколько человек. Он вел армии {link:alliance}Альянс{/link}а против Орды на севере и научился доверять силе, которая была ему дана.]=],
		},
		{
			title = "Черная гора",
			text = [=[В конце войны {link:alliance}Альянс{/link} оттеснил Орду на юг, к Черной горе. В битве у подножия горы вождь {link:orgrim-doomhammer}Оргрим Молот Рока{/link} убил главнокомандующего. Солдаты Альянса дрогнули. Туралион поднял меч своего командира и сплотил их. Паладины воззвали к {link:holy-light}Свет{/link}у, и {link:horde}Орда{/link} была сломлена. Вождя Молота Рока взяли в плен. Туралион преследовал последних {link:orcs}орк{/link}ов до Темного портала, и Альянс разрушил врата.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он был среди первых паладинов Серебряной Длани.
• Он служил помощником главнокомандующего Андуина {link:anduin-lothar}Лотар{/link}а во Вторую войну.
• Он сплотил {link:alliance}Альянс{/link} после гибели командира и выиграл битву у Черной горы.
• Он гнал Орду до Темного портала и видел, как тот был разрушен.
• Вместе с магом {link:khadgar}Кадгар{/link}ом он повел войско Альянса в мир {red:draenor}Дренор{/red}.]=],
		},
		{
			title = "За Порталом",
			text = [=[Несколько лет спустя Портал открылся снова, и через него пришли {link:orcs}орк{/link}и, чтобы украсть реликвии силы для шамана {link:ner-zhul}Нер'зула{/link}. Туралион повел войско {link:alliance}Альянс{/link}а в Дренор вместе с магом {link:khadgar}Кадгар{/link}ом. С ними пошли следопыт Аллерия Ветрокрылая, старшая сестра {link:sylvanas-windrunner}Сильваны Ветрокрылой{/link}, и другие герои войны. Войско сражалось с орками по всему их разбитому миру. Когда заклинания шамана начали рвать Дренор на части, вожди похода закрыли Портал с дальней стороны, чтобы разрушение не достигло {link:azeroth}Азерота{/link}. Вернуться домой они не могли.]=],
		},
		{
			title = "Судьба",
			text = [=[С тех пор как закрылся Портал, в королевствах его не видели. Паладины севера до сих пор произносят его имя рядом с именем паладина {link:uther-the-lightbringer}Утер{/link}а.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Ни одна летопись королевств не говорит, что стало с ним за Порталом.]=],
		},
	},
	bonds = {
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "его командир" },
		{ id = "khadgar", name = "Кадгар", note = "его спутник в двух войнах" },
		{ id = "uther-the-lightbringer", name = "Утер Светоносный", note = "брат по Серебряной Длани" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "вождь, которого он победил" },
		{ id = "alonsus-faol", name = "Алонсий Фаол", note = "посвятил его в паладины" },
	},
})

Translate("ruRU", "tirion-fordring", {
	title = "Тирион Фордринг",
	subtitle = "Изгнанный паладин",
	found = [=[Одинокая хижина у реки на западном краю Восточных Чумных земель]=],
	hint = [=[Ищите отшельника, который удит рыбу у хижины на западном краю Восточных Чумных земель.]=],
	allegiance = "Нет (прежде рыцари Серебряной Длани)",
	aliases = { "Тирион" },
	sections = {
		{
			title = "Обзор",
			text = [=[Некогда Тирион Фордринг был лордом Крепости Марденхольд и одним из первых паладинов Серебряной Длани. Его лишили земель и титулов за то, что он защитил {link:orcs}орк{/link}а, и отправили в изгнание. Теперь он живет один в хижине в {link:eastern-plaguelands}Восточных Чумных землях{/link}, старик в краю мертвых. Его сын возглавляет {link:scarlet-crusade}Алый орден{/link} в {link:hearthglen}Дольном Очаге{/link} и считает, что отец давно умер.]=],
		},
		{
			title = "Значение",
			text = [=[{link:tyrion}Тирион{/link} — человек {link:holy-light}Свет{/link}а, который сохранил честь, когда его орден и его королевство ее не сохранили. В {link:lordaeron}Лордерон{/link}е его мало кто помнит. Но {link:orcs}орк{/link}и, которые знают его историю, чтят его, и рассказ о его падении близок всякому, кому приходилось выбирать между законом и правдой.]=],
		},
		{
			title = "Серебряная Длань",
			text = [=[{link:tyrion}Тирион{/link} был среди первых рыцарей, которых обучил архиепископ {link:alonsus-faol}Алонсий Фаол{/link}; с ним были {link:uther-the-lightbringer}Утер Светоносный{/link} и {link:turalyon}Туралион{/link}. Он бился с {link:horde}Ордой{/link} во {link:second-war}Вторую войну{/link}. После войны он правил землями Дольного Очага из Крепости Марденхольд вместе с женой Карандрой и сыном {link:taelan-fordring}Телан{/link}ом.]=],
		},
		{
			title = "Суд",
			text = [=[Однажды {link:tyrion}Тирион{/link} наткнулся на старого воина-{link:orcs}орк{/link}а, который прятался в руинах близ его земель. Это был {link:eitrigg}Эйтригг{/link}. Орк мог убить его, но пощадил. Тирион увидел в нем честь и отпустил его. Когда его собственные солдаты пришли убить орка, Тирион защитил его. За это его судили за измену. Его лишили земель и титулов и изгнали из ордена. Жена сказала сыну, что отец умер, и мальчика отвели на ложную могилу отца.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он был среди первых паладинов ордена рыцарей Серебряной Длани.
• Он бился с Ордой во Вторую войну.
• Он правил Крепостью Марденхольд и землями вокруг Дольного Очага.
• Он пощадил {link:orcs}орк{/link}а {link:eitrigg}Эйтригг{/link}а и защитил его от собственных людей.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:tyrion}Тирион{/link} живет один у реки, вдали от всякой дороги. Его сын {link:taelan-fordring}Телан{/link} вырос паладином и теперь носит звание верховного лорда Алого ордена в Дольном Очаге, связанный с орденом, который сбился с пути. {link:eitrigg}Эйтригг{/link} служит вождю {link:thrall}Траллу{/link} в {link:orgrimmar}Оргриммаре{/link} и не забыл человека, который его спас.]=],
		},
	},
	chapters = {
		{
			title = "Искупление",
			hint = "Посидите со стариком у реки и выслушайте его рассказ.",
			text = [=[{link:tyrion}Тирион{/link} просил лишь, чтобы гость сел и послушал. Он рассказал о своем падении и о сыне, который вырос без него. Он не просил очистить его собственное имя. Он просил спасти сына от того, что сделал из него {link:scarlet-crusade}Алый орден{/link}.]=],
		},
		{
			title = "О забытых воспоминаниях",
			hint = "Верните игрушку с ложной могилы на юге Чумных земель.",
			text = [=[Когда мальчику было семь лет, отец подарил ему маленький боевой молот, копию своего собственного. После изгнания отца {link:taelan-fordring}Телан{/link} закопал его на ложной могиле в Крипте. Там молот и лежал с тех пор, и {link:tyrion}Тирион{/link} попросил вернуть его.]=],
		},
		{
			title = "Об утраченной чести",
			hint = "Верните то, что Телан бросил в Северном Доле.",
			text = [=[Когда пал {link:uther-the-lightbringer}Утер{/link} и Серебряная Длань была уничтожена, молодой {link:taelan-fordring}Телан{/link} сражался, сколько мог. В деревушке {link:northdale}Северный Дол{/link} он дал последний бой, и там он швырнул знамя ордена на землю и отвернулся от него. {link:tyrion}Тирион{/link} смотрел на разорванное знамя и вспоминал день, когда сам принес клятву.]=],
		},
		{
			title = "В грезах",
			hint = "Приведите сына к отцу.",
			text = [=[{link:taelan-fordring}Телан{/link} годами видел отца во сне. Вспомнив, каким он был, он покинул {link:hearthglen}Дольный Очаг{/link}, чтобы найти его. {link:scarlet-crusade}Алый орден{/link} настиг его на дороге, и верховный инквизитор Изиллиен убил его на глазах у отца. В своем горе {link:tyrion}Тирион{/link} объявил, что орден, которому он служил, не мертв. Он назвал себя верховным лордом новой Серебряной Длани, возрожденной из старой.]=],
		},
	},
	mentions = {
		{ text = "Искупление" },
		{ text = "О забытых воспоминаниях" },
		{ text = "Об утраченной чести" },
		{ text = "О любви и семье" },
		{ text = "В грезах" },
	},
	bonds = {
		{ id = "eitrigg", name = "Эйтригг", note = "орк, которого он пощадил" },
		{ id = "uther-the-lightbringer", name = "Утер Светоносный", note = "брат по Серебряной Длани" },
		{ id = "alonsus-faol", name = "Алонсий Фаол", note = "его учитель в Свете" },
		{ id = "turalyon", name = "Туралион", note = "брат по Серебряной Длани" },
	},
})

Translate("ruRU", "garona", {
	title = "Гарона",
	subtitle = "Полуорчиха",
	allegiance = "Неизвестно (прежде Совет Теней)",
	sections = {
		{
			title = "Обзор",
			text = [=[Гарона была полуорчихой смешанной крови, лазутчицей и посланницей {link:horde}Орды{/link} в {link:first-war}Первую войну{/link}. Чернокнижник {link:gul-dan}Гул'дан{/link} послал ее в башню, где жил {link:medivh}Медив{/link}. Там она подружилась с молодым магом {link:khadgar}Кадгаром{/link}, а потом стала служить королю {link:stormwind-city}Штормград{/link}а {link:llane-wrynn}Ллейну Ринну{/link}. Она же его и убила.]=],
		},
		{
			title = "Значение",
			text = [=[Гарона помогла донести до {link:stormwind-city}Штормград{/link}а правду об измене Хранителя, и она нанесла удар, который оборвал жизнь его короля. Оба дела были ее, и ни одно не было вполне ее собственным.]=],
		},
		{
			title = "Посланница и лазутчица",
			text = [=[{link:orcs}Орки{/link} презирали ее за смешанную кровь, и она рано научилась выживать своим умом. {link:shadow-council}Совет Теней{/link}, которым правил {link:gul-dan}Гул'дан{/link}, пользовался ею. Она пришла в {link:karazhan}Каражан{/link} посланницей Орды к Хранителю. Там она и {link:khadgar}Кадгар{/link} узнали, что орков в {link:azeroth}Азерот{/link} привел сам {link:medivh}Медив{/link}. Она стояла рядом с Кадгаром и {link:anduin-lothar}Андуином Лотаром{/link}, когда Хранитель был убит. Потом она поступила на службу в {link:stormwind-city}Штормград{/link}е и стала доверенной советницей короля.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она была посланницей Орды к Хранителю в {link:karazhan}Каражан{/link}е.
• Она помогла магу {link:khadgar}Кадгар{/link}у раскрыть предательство, которое совершил {link:medivh}Медив{/link}.
• Она была при смерти Хранителя.
• Она убила короля {link:llane-wrynn}Ллейн{/link}а Ринна в его собственной крепости.]=],
		},
		{
			title = "Судьба",
			text = [=[Ее разум не принадлежал ей. Чернокнижники {link:shadow-council}Совет{/link}а Теней имели тайную власть над ее волей. Когда {link:orgrim-doomhammer}Оргрим Молот Рока{/link} осадил {link:stormwind-city}Штормград{/link} в последний раз, она убила короля в его покоях, и юный принц {link:varian-wrynn}Вариан Ринн{/link} это видел. Потом она бежала. Никто в королевствах не знает, куда она ушла.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Куда ушла Гарона после падения {link:stormwind-city}Штормград{/link}а и жива ли она еще, летописи не говорят.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Ллейн Ринн", note = "ее король и ее жертва" },
		{ id = "khadgar", name = "Кадгар", note = "ее друг в Каражане" },
		{ id = "medivh", name = "Медив", note = "Хранитель, к которому она была послана" },
		{ id = "gul-dan", name = "Гул'дан", note = "ее хозяин" },
	},
})

Translate("ruRU", "alexstrasza", {
	title = "Алекстраза",
	subtitle = "Королева красных драконов",
	allegiance = "Род красных драконов",
	aliases = { "Алекстраза Хранительница Жизни" },
	sections = {
		{
			title = "Обзор",
			text = [=[Алекстраза — Аспект рода красных драконов, Королева драконов, хранительница жизни. В древние дни творцы мира дали ей власть над всем живым. Она стерегла {link:azeroth}Азерот{/link} еще до того, как эльфы построили свои первые города. В годы {link:second-war}Второй войны{/link} она была пленницей {link:orcs}орк{/link}ов, а из ее детей сделали оружие войны.]=],
		},
		{
			title = "Значение",
			text = [=[Ни один смертный народ не пострадал от предательства {link:deathwing}Смертокрыла{/link} больше, чем красные драконы. Их плен в {link:grim-batol}Грим Батоле{/link} дал {link:horde}Орде{/link} ее драконов, и он до сих пор причина ненависти между красным родом и {link:orcs}орк{/link}ами {link:dragonmaw-clan}клана Драконьей Пасти{/link}.]=],
		},
		{
			title = "Аспекты",
			text = [=[В древние дни пять великих драконов были избраны стеречь мир. Величайшая из них, Алекстраза, стала хранительницей всей жизни. Страж Земли {link:deathwing}Нелтарион{/link} был ее собратом. В {link:war-of-the-ancients}Войну древних{/link} он убедил Аспектов отдать часть своей силы его большому золотому диску, Душе Дракона, а потом обратил его против них. Драконов рассеяло, и красный род тяжко пострадал. Алекстраза никогда этого не забыла.]=],
		},
		{
			title = "Грим Батол",
			text = [=[Во Вторую войну Душа Дракона попала в руки {link:orcs}орк{/link}ов клана Драконьей Пасти. Ее силой они схватили королеву и сковали ее под горой {link:grim-batol}Грим Батол{/link} в {link:wetlands}Болотине{/link}. Они забирали ее яйца, едва она их откладывала, и растили ее детенышей как боевых ездовых зверей. Красные драконы летали за Орду против {link:alliance}Альянса{/link} и жгли леса {link:quel-thalas}Кель'Таласа{/link} и города севера.]=],
		},
		{
			title = "Деяния",
			text = [=[• В древние дни ее избрали Аспектом жизни.
• В Войну древних ее предал {link:deathwing}Нелтарион{/link}.
• {link:dragonmaw-clan}Клан Драконьей Пасти{/link} держал ее в плену в {link:grim-batol}Грим Батол{/link}е.
• Ее освободили, и она видела, как была уничтожена Душа Дракона.]=],
		},
		{
			title = "Наши дни",
			text = [=[Долго после войны {link:dragonmaw-clan}клан Драконьей Пасти{/link} все еще держал королеву. {link:deathwing}Смертокрыл{/link} пришел в {link:grim-batol}Грим Батол{/link} за ее яйцами, желая забрать ее детей себе. Небольшой отряд героев и драконов освободил пленницу. Душа Дракона была уничтожена, и сила королевы вернулась. Красные драконы обрушились на своих тюремщиков и прогнали Смертокрыла. Клан Драконьей Пасти до сих пор цепляется за Болотину, и красные драконы до сих пор на него охотятся. Где теперь обитает сама Королева драконов, знают немногие смертные.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Летописи королевств мало говорят о том, куда ушла Королева драконов после своего освобождения.]=],
		},
	},
	bonds = {
		{ id = "deathwing", name = "Смертокрыл", note = "собрат-Аспект и ее предатель" },
		{ id = "queen-azshara", name = "Королева Азшара", note = "в чью войну Аспекты были преданы" },
	},
})

Translate("ruRU", "cenarius", {
	title = "Кенарий",
	subtitle = "Владыка леса",
	allegiance = "Леса Калимдора · Круг Кенария",
	sections = {
		{
			title = "Обзор",
			text = [=[Кенарий был полубогом дикой природы, владыкой лесов {link:kalimdor}Калимдора{/link}. {link:night-elves}Ночные эльфы{/link} считали его сыном своей богини луны Элуны. Он был учителем друида {link:malfurion-stormrage}Малфуриона Ярости Бури{/link} и отцом друидических искусств среди смертных. Он пал в {link:third-war}Третью войну{/link}: его убил {link:grom-hellscream}Гром Адский Крик{/link} в чащах {link:ashenvale}Ясеневого леса{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Каждый друид, который ходит по миру, идет путем, который открыл Кенарий. {link:cenarion-circle}Круг Кенария{/link}, который собирает вместе друидов из ночных эльфов и {link:tauren}тауренов{/link}, носит его имя. Его смерть стала раной для лесов {link:kalimdor}Калимдор{/link}а, и ночные эльфы ее не простили.]=],
		},
		{
			title = "Первый друид",
			text = [=[В век до {link:war-of-the-ancients}Войны древних{/link} Кенарий жил в рощах горы Хиджал. Он взял в ученики молодого эльфа и научил его придавать облик силам природы. Когда {link:burning-legion}Пылающий Легион{/link} пришел через {link:well-of-eternity}Источник Вечности{/link}, Кенарий повел древних духов леса в бой рядом с ночными эльфами. После {link:great-sundering}Великого Раскола{/link} друиды ордена, который основал {link:malfurion-stormrage}Малфурион{/link}, приняли его учение и хранили его десять тысяч лет. Его имя жило в Роге Кенария, в который Малфурион однажды протрубит у подножия Мирового Древа.]=],
		},
		{
			title = "Его дети",
			text = [=[У него было много детей. Говорят, что дриады и хранители рощ — его потомство. Его сын Зейтар был отцом первых {link:centaurs}кентавр{/link}ов, народа, который теперь мало что помнит о нем, кроме его гнева. Его сын {link:keeper-remulos}Ремулос{/link} хранит священную рощу {link:moonglade}Лунной поляны{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он научил друида {link:malfurion-stormrage}Малфурион{/link}а и первых друидов путям природы.
• Он вел духов леса в Войну древних.
• Он стерег леса {link:kalimdor}Калимдор{/link}а десять тысяч лет.
• Он бился с {link:orcs}орк{/link}ами, которые пришли рубить деревья Ясеневого леса.
• Рог, который носит его имя, созвал духов древних против владыки демонов {link:archimonde}Архимонда{/link} в {link:battle-of-mount-hyjal}Битве у горы Хиджал{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[В Третью войну {link:orcs}орк{/link}и клана Песни Войны пришли в {link:ashenvale}Ясеневый лес{/link} рубить деревья. {link:night-elves}Ночные эльфы{/link} дрались с ними, и Кенарий пришел защитить свой лес. Орки не могли выстоять против него. В отчаянии {link:grom-hellscream}Гром Адский Крик{/link} и его воины напились из источника, оскверненного кровью демона {link:mannoroth}Маннорота{/link}, и старая ярость сошла на них. В этой ярости они убили полубога. Кенарий мертв. Его друиды до сих пор чтят его, а его дети до сих пор стерегут его рощи.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Пережила ли его смерть какая-нибудь из его сил, летописи не говорят.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Малфурион Ярость Бури", note = "его ученик" },
		{ id = "grom-hellscream", name = "Гром Адский Крик", note = "его убийца" },
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "брат его ученика" },
		{ id = "mannoroth", name = "Маннорот", note = "чья кровь свела с ума его убийц" },
	},
})

Translate("ruRU", "kil-jaeden", {
	title = "Кил'джеден",
	subtitle = "Обманщик",
	allegiance = "Пылающий Легион",
	aliases = { "Кил'джеден Обманщик" },
	sections = {
		{
			title = "Обзор",
			text = [=[Кил'джеден Обманщик — один из великих владык {link:burning-legion}Пылающего Легиона{/link}, и над ним только воля темного титана {link:sargeras}Саргераса{/link}. Некогда он был вождем эредаров вместе с {link:archimonde}Архимондом{/link} и, как и тот, принял предложение темного титана. Он мастер лжи. Именно Кил'джеден совратил {link:orcs}орк{/link}ов мира {red:draenor}Дренор{/red}, и именно он создал {red:lich-king}Короля-лича{/red}.]=],
		},
		{
			title = "Значение",
			text = [=[Мало в каком из бедствий последнего поколения нет руки Обманщика. Через двоих {link:orcs}орк{/link}ов, {link:ner-zhul}Нер'зула{/link} и {link:gul-dan}Гул'дана{/link}, он превратил орков в оружие. Через Короля-лича он спустил {link:scourge}Плеть{/link} на {link:lordaeron}Лордерон{/link}. В отличие от своего собрата, он ни разу не был побежден.]=],
		},
		{
			title = "Эредары",
			text = [=[Давным-давно эредарами правили трое вождей: Кил'джеден, {link:archimonde}Архимонд{/link} и Велен. {link:sargeras}Саргерас{/link} пришел к ним с обещаниями знания и силы. Кил'джеден и Архимонд согласились, и они и их народ были искажены в демонов. Велен отказался и бежал со своими сторонниками. Кил'джеден возненавидел его за это и поклялся охотиться на его народ, куда бы тот ни ушел.]=],
		},
		{
			title = "Орки",
			text = [=[Народ, который вел Велен, дренеи, пришел наконец в Дренор, где жили {link:orcs}орк{/link}и. Там Кил'джеден их и нашел. Он явился старому шаману {link:ner-zhul}Нер'зул{/link}у в облике духа предков и сказал ему, что дренеи замышляют зло против его народа. Когда Нер'зул начал сомневаться в нем, Обманщик обратился к его ученику и обучил его искусству {link:fel-magic}магии Скверны{/link}. Через этого ученика, чернокнижника {link:gul-dan}Гул'дан{/link}а, он дал оркам кровь демона {link:mannoroth}Маннорота{/link}, привязал их к Легиону и натравил на дренеев.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он принял то, что предложил {link:sargeras}Саргерас{/link}, и стал владыкой Легиона.
• Он обманул шамана {link:ner-zhul}Нер'зул{/link}а и обратил {link:orcs}орк{/link}ов против дренеев.
• Он обучил чернокнижника {link:gul-dan}Гул'дан{/link}а искусству магии Скверны.
• Он превратил шамана Нер'зула в Короля-лича.
• Он послал Короля-лича готовить {link:azeroth}Азерот{/link} к приходу Легиона.]=],
		},
		{
			title = "Король-лич",
			text = [=[Когда {link:ner-zhul}Нер'зул{/link} бежал из гибнущего Дренора, Кил'джеден ждал его. Он сорвал с шамана тело и заключил его дух в доспехи и шлем. Он запечатал его во льду и сбросил на {red:northrend}Нордскол{/red}, повелев разнести чуму, которая ослабит мир перед приходом Легиона. Король-лич так и сделал. Когда {link:archimonde}Архимонд{/link} пал у {link:mount-hyjal}горы Хиджал{/link}, Обманщик узнал, что его слуга начал выскальзывать из цепей.]=],
		},
		{
			title = "Судьба",
			text = [=[Кил'джеден не ступал на землю {link:azeroth}Азерота{/link}. После Третьей войны он добивался, чтобы Короля-лича уничтожили чужими руками. Король-лич держится, а Обманщик по-прежнему наблюдает из-за пределов мира.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Летописи не говорят, где обитает Кил'джеден и что он замышляет теперь.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Архимонд", note = "такой же владыка Легиона" },
		{ id = "sargeras", name = "Саргерас", note = "его хозяин" },
		{ id = "ner-zhul", name = "Нер'зул", note = "шаман, которого он обманул и превратил в Короля-лича" },
		{ id = "gul-dan", name = "Гул'дан", note = "его слуга среди орков" },
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "которого он послал против Короля-лича" },
	},
})

Translate("ruRU", "sargeras", {
	title = "Саргерас",
	subtitle = "Владыка Пылающего Легиона",
	allegiance = "Пылающий Легион",
	aliases = { "Темный титан" },
	sections = {
		{
			title = "Обзор",
			text = [=[Саргерас — хозяин {link:burning-legion}Пылающего Легиона{/link}, падший титан, который стремится уничтожить все сотворенное. Некогда он был величайшим защитником титанов, творцов миров, и несчетные века сражался с демонами {link:krueg-skullsplitter}Круг{/link}оверти Пустоты. Со временем он отчаялся в своем труде. Он освободил демонов, которых заточил, собрал их в войско и обратил его против всякого мира, которому титаны придали облик.]=],
		},
		{
			title = "Значение",
			text = [=[Всякую войну, которую Легион вел против {link:azeroth}Азерота{/link}, он вел во имя своего хозяина. Трижды Саргерас дотягивался до мира: через {link:queen-azshara}королеву Азшару{/link}, через Хранительницу {link:aegwynn}Эгвин{/link} и ее сына {link:medivh}Медива{/link} и через {link:orcs}орк{/link}ов, которых подчинил своей воле. Его тень лежит за {link:war-of-the-ancients}Войной древних{/link}, {link:first-war}Первой войной{/link} и {link:third-war}Третьей войной{/link}.]=],
		},
		{
			title = "Падший титан",
			text = [=[Летописи говорят, что Саргерас охотился на демонов по всей Великой Тьме дольше, чем может счесть любой смертный. То, что он там увидел, перевернуло его сердце. Он поверил, что само творение порочно и исправить его нельзя. Он выпустил на волю пойманных им демонов и совратил эредаров через двоих вождей, {link:archimonde}Архимонда{/link} и {link:kil-jaeden}Кил'джедена{/link}, и так родился Легион.]=],
		},
		{
			title = "Азерот",
			text = [=[Десять тысяч лет назад королева {link:azshara}Азшара{/link} и ее высокорожденные привлекли его взор силой {link:well-of-eternity}Источника Вечности{/link}. Саргерас послал свой Легион через их портал и стремился войти в мир сам. Источник уничтожили прежде, чем он успел. Века спустя он явился перед Хранительницей {link:aegwynn}Эгвин{/link} в великой буре в {red:northrend}Нордсколе{/red}. Она убила его аватару и запечатала ее тело в гробнице под морем. Его дух укрылся в ней и перешел в ее нерожденного сына. Через этого сына темный титан открыл {link:dark-portal}Темный портал{/link} и привел {link:orcs}орк{/link}ов в {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Некогда он был защитником титанов.
• Он освободил демонов, которых заточил, и основал {link:burning-legion}Пылающий Легион{/link}.
• Он совратил эредаров через вождей {link:archimonde}Архимонд{/link}а и {link:kil-jaeden}Кил'джеден{/link}а.
• Он шептал королеве Азшаре и едва не вошел в мир.
• Он укрывался в Хранительнице {link:aegwynn}Эгвин{/link} и в ее сыне и через него открыл {link:dark-portal}Темный портал{/link}.]=],
		},
		{
			title = "Судьба",
			text = [=[Саргерас никогда не ступал по {link:azeroth}Азерот{/link}у в своем истинном облике. Его аватара лежит в гробнице под морем, которую поднял чернокнижник {link:gul-dan}Гул'дан{/link} и в которую тот вошел себе на погибель. Когда {link:medivh}Медив{/link} был убит, хватка темного титана на мире разжалась. Но Легион, который он ведет, остался, и его владыки не отказались от своей жажды этого мира.]=],
		},
		{
			title = "Чего не знают летописи",
			text = [=[Что стало с духом темного титана, когда умер {link:medivh}Медив{/link}, летописи королевств сказать не могут.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Архимонд", note = "его полководец" },
		{ id = "kil-jaeden", name = "Кил'джеден", note = "его полководец" },
		{ id = "aegwynn", name = "Эгвин", note = "убила его аватару" },
		{ id = "medivh", name = "Медив", note = "его сосуд" },
		{ id = "queen-azshara", name = "Королева Азшара", note = "его служанка" },
		{ id = "illidan-stormrage", name = "Иллидан Ярость Бури", note = "получил его дар" },
	},
})

Translate("ruRU", "mannoroth", {
	title = "Маннорот",
	subtitle = "Губитель",
	allegiance = "Пылающий Легион",
	aliases = { "Маннорот Губитель" },
	sections = {
		{
			title = "Обзор",
			text = [=[Маннорот Губитель был властителем преисподней из {link:burning-legion}Пылающего Легиона{/link}, исполинским демоном с рогами и бивнями. Он вел армии Легиона в {link:war-of-the-ancients}Войну древних{/link}. Позже его кровь привязала {link:orcs}орк{/link}ов мира {red:draenor}Дренор{/red} к Легиону. Его убил в {link:ashenvale}Ясеневом лесу{/link} {link:grom-hellscream}Гром Адский Крик{/link}, первый орк, который ее выпил.]=],
		},
		{
			title = "Значение",
			text = [=[Проклятием {link:orcs}орк{/link}ов была кровь этого демона. Она дала им силу и ярость, и она же сделала их рабами. Его смерть освободила их, и потому {link:horde}Орда{/link}, которую ведет {link:thrall}Тралл{/link}, родилась свободной.]=],
		},
		{
			title = "Кровь",
			text = [=[В Войну древних Маннорот повелевал демонами, которые хлынули через {link:well-of-eternity}Источник Вечности{/link}. Когда Легион обратился к Дренору, чернокнижник {link:gul-dan}Гул'дан{/link} собрал вождей {link:orcs}орк{/link}ов и предложил им чашу с кровью властителя преисподней. Гром выпил первым, а другие — за ним. Их народ стал Ордой ярости, подчиненной воле Легиона. Много позже, в {link:third-war}Третью войну{/link}, Маннорот пришел в {link:ashenvale}Ясеневый лес{/link}. Когда Гром и его клан Песни Войны отчаялись одолеть защитников леса, они напились из источника, который Маннорот осквернил своей кровью. В ярости, которая пришла потом, они убили полубога {link:cenarius}Кенария{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он вел армии Легиона в Войну древних.
• Его кровь привязала {link:orcs}орк{/link}ов Дренора к Легиону.
• Он осквернил источник в Ясеневом лесу и поработил клан Песни Войны во второй раз.]=],
		},
		{
			title = "Судьба",
			text = [=[{link:thrall}Тралл{/link} и Гром вместе пошли на властителя преисподней в один из каньонов Ясеневого леса. Маннорот сразил вождя Тралла. Гром бросился вперед один и вогнал топор в грудь демона. Маннорот умер, и проклятие {link:orcs}орк{/link}ов было снято. Гром умер от ран. Тот каньон до сих пор зовут Каньоном Гибели Демона.]=],
		},
	},
	bonds = {
		{ id = "grom-hellscream", name = "Гром Адский Крик", note = "первым выпил его кровь и стал его убийцей" },
		{ id = "gul-dan", name = "Гул'дан", note = "дал его кровь оркам" },
		{ id = "archimonde", name = "Архимонд", note = "такой же владыка Легиона" },
		{ id = "cenarius", name = "Кенарий", note = "убит теми, кого свела с ума его кровь" },
		{ id = "thrall", name = "Тралл", note = "бился с ним вместе с вождем Громом" },
	},
})
